/* ── Helper: create temp test repo with known layout ───────────── */

static char g_tmpdir[256];

/* Create:
 *   /tmp/cbm_test_XXXXXX/
 *     main.go       (empty)
 *     pkg/
 *       service.go  (empty)
 *       util/
 *         helper.go (empty)
 */
static int setup_test_repo(void) {
    snprintf(g_tmpdir, sizeof(g_tmpdir), "/tmp/cbm_test_XXXXXX");
    if (!cbm_mkdtemp(g_tmpdir))
        return -1;

    char path[512];

    /* main.go — calls Serve() from pkg */
    snprintf(path, sizeof(path), "%s/main.go", g_tmpdir);
    FILE *f = fopen(path, "w");
    if (!f)
        return -1;
    fprintf(f, "package main\n\n"
               "import \"pkg\"\n\n"
               "func main() {\n"
               "\tpkg.Serve()\n"
               "}\n");
    fclose(f);

    /* pkg/ */
    snprintf(path, sizeof(path), "%s/pkg", g_tmpdir);
    cbm_mkdir(path);

    /* pkg/service.go — calls Help() from util */
    snprintf(path, sizeof(path), "%s/pkg/service.go", g_tmpdir);
    f = fopen(path, "w");
    if (!f)
        return -1;
    fprintf(f, "package pkg\n\n"
               "import \"pkg/util\"\n\n"
               "func Serve() {\n"
               "\tutil.Help()\n"
               "}\n");
    fclose(f);

    /* pkg/util/ */
    snprintf(path, sizeof(path), "%s/pkg/util", g_tmpdir);
    cbm_mkdir(path);

    /* pkg/util/helper.go */
    snprintf(path, sizeof(path), "%s/pkg/util/helper.go", g_tmpdir);
    f = fopen(path, "w");
    if (!f)
        return -1;
    fprintf(f, "package util\n\nfunc Help() {}\n");
    fclose(f);

    return 0;
}

/* Recursive remove (simple, not production-grade) */
static void rm_rf(const char *path) {
    th_rmtree(path);
}

static void teardown_test_repo(void) {
    if (g_tmpdir[0])
        rm_rf(g_tmpdir);
    g_tmpdir[0] = '\0';
}

/* ── Lifecycle tests ─────────────────────────────────────────────── */

TEST(pipeline_create_free) {
    cbm_pipeline_t *p = cbm_pipeline_new("/some/path", NULL, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    ASSERT_STR_EQ(cbm_pipeline_project_name(p), "some-path");
    cbm_pipeline_free(p);
    PASS();
}

TEST(pipeline_null_repo) {
    cbm_pipeline_t *p = cbm_pipeline_new(NULL, NULL, CBM_MODE_FULL);
    ASSERT_NULL(p);
    PASS();
}

TEST(pipeline_free_null) {
    cbm_pipeline_free(NULL); /* should not crash */
    PASS();
}

TEST(pipeline_cancel) {
    cbm_pipeline_t *p = cbm_pipeline_new("/some/path", NULL, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    cbm_pipeline_cancel(p);
    /* Running a cancelled pipeline should return -1 immediately */
    int rc = cbm_pipeline_run(p);
    /* Note: it may fail because /some/path doesn't exist, not because of cancel.
     * This test just verifies cancel doesn't crash. */
    (void)rc;
    cbm_pipeline_free(p);
    PASS();
}

TEST(pipeline_cancel_null) {
    cbm_pipeline_cancel(NULL); /* should not crash */
    PASS();
}

TEST(pipeline_run_null) {
    int rc = cbm_pipeline_run(NULL);
    ASSERT_EQ(rc, -1);
    PASS();
}

TEST(pipeline_discovery_limit_returns_exact_violation_without_publishing) {
    char *repo = th_mktempdir("cbm_pipeline_discovery_limit");
    ASSERT_NOT_NULL(repo);
    ASSERT_EQ(th_write_file(TH_PATH(repo, "first.c"), "int first;\n"), 0);
    ASSERT_EQ(th_write_file(TH_PATH(repo, "second.py"), "second = 2\n"), 0);

    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/index.db", repo);
    cbm_pipeline_t *pipeline = cbm_pipeline_new(repo, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(pipeline);
    cbm_index_resource_policy_t policy;
    cbm_index_policy_init(&policy);
    policy.max_files = (cbm_index_limit_u64_t){.enabled = true, .value = 1};
    cbm_pipeline_set_resource_policy(pipeline, &policy);

    ASSERT_EQ(cbm_pipeline_run(pipeline), CBM_PIPELINE_RESOURCE_LIMIT);
    cbm_index_resource_violation_t violation = {0};
    cbm_pipeline_get_resource_violation(pipeline, &violation);
    ASSERT_EQ(violation.resource, CBM_INDEX_RESOURCE_FILES);
    ASSERT_EQ(violation.observed, 2);
    ASSERT_EQ(violation.limit, 1);
    ASSERT_FALSE(cbm_file_exists(db_path));

    cbm_pipeline_free(pipeline);
    th_cleanup(repo);
    PASS();
}

/* ── Focused: file-backed store persistence ─────────────────────── */

TEST(store_file_persistence) {
    if (setup_test_repo() != 0) {
        FAIL("failed to create temp dir");
    }
    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/persist_test.db", g_tmpdir);

    /* Write data */
    cbm_store_t *s1 = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s1);
    cbm_store_upsert_project(s1, "proj", "/tmp");
    cbm_node_t n = {.project = "proj",
                    .label = "Function",
                    .name = "foo",
                    .qualified_name = "proj.foo",
                    .file_path = "f.go"};
    int64_t id = cbm_store_upsert_node(s1, &n);
    ASSERT_GT(id, 0);
    int cnt1 = cbm_store_count_nodes(s1, "proj");
    ASSERT_EQ(cnt1, 1);
    cbm_store_checkpoint(s1);
    cbm_store_close(s1);

    /* Reopen and verify */
    cbm_store_t *s2 = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s2);
    int cnt2 = cbm_store_count_nodes(s2, "proj");
    ASSERT_EQ(cnt2, 1);
    cbm_store_close(s2);

    teardown_test_repo();
    PASS();
}

TEST(store_bulk_persistence) {
    if (setup_test_repo() != 0) {
        FAIL("failed to create temp dir");
    }
    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/bulk_test.db", g_tmpdir);

    /* Verify: begin_bulk + explicit txn + end_bulk persists to file */
    cbm_store_t *s = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s);

    cbm_store_upsert_project(s, "proj", "/tmp");
    cbm_store_begin_bulk(s);
    cbm_store_begin(s);
    cbm_node_t n = {.project = "proj",
                    .label = "Function",
                    .name = "foo",
                    .qualified_name = "proj.foo",
                    .file_path = "f.go"};
    int64_t id = cbm_store_upsert_node(s, &n);
    ASSERT_GT(id, 0);
    ASSERT_EQ(cbm_store_commit(s), 0);
    cbm_store_end_bulk(s);
    cbm_store_checkpoint(s);
    cbm_store_close(s);

    /* Reopen and verify data survived */
    cbm_store_t *s2 = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s2);
    ASSERT_EQ(cbm_store_count_nodes(s2, "proj"), 1);
    cbm_store_close(s2);

    teardown_test_repo();
    PASS();
}

static void write_temp_file(const char *dir, const char *name, const char *content);

/* EVERY proto service gets its Routes, not the first 64 the graph buffer
 * happened to hold.
 *
 * create_grpc_routes() collected services into a fixed `services[CBM_SZ_64]`
 * and stopped there, in graph-buffer insertion order — which is parallel
 * worker merge order. So on a repo with more than 64 services the extras were
 * silently dropped, and WHICH ones were dropped changed between runs of the
 * same binary: two kubernetes indexes differed by 5 Routes one way and 4 the
 * other, plus their HANDLES edges (2026-09-18). 70 services here, so the old
 * cap fails this test whatever order the workers produce. */
TEST(pipeline_grpc_routes_cover_every_service_past_the_old_cap) {
    char tmp[256];
    snprintf(tmp, sizeof(tmp), "/tmp/cbm_grpc_cap_XXXXXX");
    ASSERT_NOT_NULL(cbm_mkdtemp(tmp));

    enum { SERVICES = 70 }; /* > the 64 the fixed array used to hold */
    for (int i = 0; i < SERVICES; i++) {
        char name[64];
        char body[512];
        snprintf(name, sizeof(name), "svc%02d.proto", i);
        snprintf(body, sizeof(body),
                 "syntax = \"proto3\";\npackage demo%02d;\n\n"
                 "message Req%02d { string id = 1; }\n"
                 "message Resp%02d { string ok = 1; }\n\n"
                 "service Svc%02d {\n"
                 "  rpc Ping (Req%02d) returns (Resp%02d);\n}\n",
                 i, i, i, i, i, i);
        write_temp_file(tmp, name, body);
    }

    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/grpc.db", tmp);
    cbm_pipeline_t *p = cbm_pipeline_new(tmp, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    ASSERT_EQ(cbm_pipeline_run(p), 0);

    cbm_store_t *s = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s);
    const char *project = cbm_pipeline_project_name(p);
    cbm_node_t *routes = NULL;
    int route_count = 0;
    ASSERT_EQ(cbm_store_find_nodes_by_label(s, project, "Route", &routes, &route_count),
              CBM_STORE_OK);
    int grpc_routes = 0;
    for (int i = 0; i < route_count; i++) {
        if (routes[i].qualified_name &&
            strncmp(routes[i].qualified_name, "__grpc__", strlen("__grpc__")) == 0) {
            grpc_routes++;
        }
    }
    cbm_store_free_nodes(routes, route_count);
    cbm_store_close(s);
    cbm_pipeline_free(p);
    th_rmtree(tmp);

    /* One rpc per service: every service must be represented. The old cap
     * produced at most 64 however the workers interleaved. */
    ASSERT_EQ(grpc_routes, SERVICES);
    PASS();
}

/* Pipeline-level: the doclinks pass runs as part of a real index and its
 * REFERENCES_FILE edges land in the store, not just in a unit test that
 * calls cbm_pipeline_pass_doclinks() directly. Registration-list gap: every
 * doclinks unit test calls the pass function by hand, so deleting its
 * {predump_doclinks, "doclinks", false} entry in pipeline.c would leave
 * every one of them green. */
TEST(pipeline_doclinks_edge_lands_in_store) {
    char tmp[256];
    snprintf(tmp, sizeof(tmp), "/tmp/cbm_doclinks_pipeline_XXXXXX");
    ASSERT_NOT_NULL(cbm_mkdtemp(tmp));

    write_temp_file(tmp, "README.md", "See [main](src/main.go) for the entry point.\n");
    write_temp_file(tmp, "src/main.go", "package main\n\nfunc main() {}\n");

    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/doclinks.db", tmp);
    cbm_pipeline_t *p = cbm_pipeline_new(tmp, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    ASSERT_EQ(cbm_pipeline_run(p), 0);

    cbm_store_t *s = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s);
    const char *project = cbm_pipeline_project_name(p);
    ASSERT_GT(cbm_store_count_edges_by_type(s, project, "REFERENCES_FILE"), 0);
    cbm_store_close(s);
    cbm_pipeline_free(p);
    th_rmtree(tmp);
    PASS();
}

/* #1735: every node and edge of a stored index, one sorted line each. */
static void graph_listing_append(sqlite3 *db, const char *sql, const char *project, char **buf,
                                 size_t *len) {
    sqlite3_stmt *stmt = NULL;
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        return;
    }
    sqlite3_bind_text(stmt, 1, project, -1, SQLITE_TRANSIENT);
    while (sqlite3_step(stmt) == SQLITE_ROW) {
        const char *row = (const char *)sqlite3_column_text(stmt, 0);
        size_t n = row ? strlen(row) : 0;
        char *grown = realloc(*buf, *len + n + 2);
        if (!grown) {
            break;
        }
        *buf = grown;
        memcpy(*buf + *len, row ? row : "", n);
        (*buf)[*len + n] = '\n';
        *len += n + 1;
        (*buf)[*len] = '\0';
    }
    sqlite3_finalize(stmt);
}

static char *graph_listing(const char *db_path, const char *project) {
    sqlite3 *db = NULL;
    if (sqlite3_open_v2(db_path, &db, SQLITE_OPEN_READONLY, NULL) != SQLITE_OK) {
        sqlite3_close(db);
        return NULL;
    }
    char *buf = calloc(1, 1);
    size_t len = 0;
    graph_listing_append(db,
                         "SELECT label||'|'||name||'|'||qualified_name||'|'||file_path||'|'||"
                         "start_line||'|'||end_line||'|'||properties FROM nodes "
                         "WHERE project=?1 ORDER BY 1",
                         project, &buf, &len);
    graph_listing_append(db,
                         "SELECT e.type||'|'||s.qualified_name||'|'||t.qualified_name||'|'||"
                         "e.properties FROM edges e JOIN nodes s ON s.id=e.source_id "
                         "JOIN nodes t ON t.id=e.target_id WHERE e.project=?1 ORDER BY 1",
                         project, &buf, &len);
    sqlite3_close(db);
    return buf;
}

static char *index_and_list(const char *repo, const char *db_name) {
    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/%s", repo, db_name);
    cbm_pipeline_t *p = cbm_pipeline_new(repo, db_path, CBM_MODE_FULL);
    if (!p) {
        return NULL;
    }
    char *listing =
        cbm_pipeline_run(p) == 0 ? graph_listing(db_path, cbm_pipeline_project_name(p)) : NULL;
    cbm_pipeline_free(p);
    return listing;
}

/* True if every line of `sub` is a line of `super`. */
static bool listing_lines_within(const char *sub, const char *super) {
    for (const char *line = sub; *line;) {
        const char *nl = strchr(line, '\n');
        size_t n = nl ? (size_t)(nl - line) : strlen(line);
        bool found = false;
        for (const char *p = super; *p && !found;) {
            const char *pnl = strchr(p, '\n');
            size_t pn = pnl ? (size_t)(pnl - p) : strlen(p);
            found = pn == n && memcmp(p, line, n) == 0;
            p = pnl ? pnl + 1 : p + pn;
        }
        if (!found) {
            fprintf(stderr, "  missing from the cut index: %.*s\n", (int)n, line);
            return false;
        }
        line = nl ? nl + 1 : line + n;
    }
    return true;
}

/* A small dump: two tables, a view, three INSERTs of 200 rows, each with one
 * subquery row and one function-call row among literal rows. */
static char *sql_dump_small(bool mysql_esc) {
    size_t cap = 256 * 1024;
    char *src = malloc(cap);
    if (!src) {
        return NULL;
    }
    const char *quoted = mysql_esc ? "(%d,'O\\'Brien',DEFAULT)" : "(%d,'O''Brien',DEFAULT)";
    size_t len = (size_t)snprintf(src, cap,
                                  "CREATE TABLE city (ID int, Name char(35), Population int);\n"
                                  "CREATE TABLE country (Code char(3), Name char(52));\n"
                                  "CREATE VIEW big_cities AS SELECT Name FROM city "
                                  "WHERE Population > 1000000;\n");
    for (int s = 0; s < 3; s++) {
        len += (size_t)snprintf(src + len, cap - len, "INSERT INTO `city` VALUES ");
        for (int r = 0; r < 200; r++) {
            if (r) {
                src[len++] = ',';
            }
            int id = s * 1000 + r;
            if (r == 100) {
                len += (size_t)snprintf(src + len, cap - len,
                                        "((SELECT MAX(Code) FROM country),'x',1)");
            } else if (r == 101) {
                len += (size_t)snprintf(src + len, cap - len, "(%d,UPPER('y'),2)", id);
            } else if (r % 3) {
                len += (size_t)snprintf(src + len, cap - len, quoted, id);
            } else {
                len += (size_t)snprintf(src + len, cap - len, "(%d,_binary 'ab',NULL)", id);
            }
        }
        len += (size_t)snprintf(src + len, cap - len, ";\n");
    }
    return src;
}

/* #1735: leaving a dump's literal INSERT rows out of the parse must not change
 * the graph. The same repository is indexed twice — once as shipped and once
 * with the full parse (test seam) — and the stored nodes and edges compared.
 * Standard '' escapes, which the SQL grammar reads correctly: identical.
 * MySQL \' escapes, which it misreads: the full parse's error recovery swallows
 * neighbouring rows, so the cut index must hold everything the full one has
 * (and may hold more — the rows the full parse lost). */
TEST(pipeline_sql_dump_graph_matches_the_full_parse_issue1735) {
    for (int esc = 0; esc < 2; esc++) {
        char tmp[256];
        snprintf(tmp, sizeof(tmp), "/tmp/cbm_sql_dump_XXXXXX");
        ASSERT_NOT_NULL(cbm_mkdtemp(tmp));
        char *src = sql_dump_small(esc == 1);
        ASSERT_NOT_NULL(src);
        write_temp_file(tmp, "dump.sql", src);
        free(src);

        char *cut = index_and_list(tmp, "cut.db");
        cbm_setenv("CBM_TEST_SQL_FULL_PARSE_ON", "dump.sql", 1);
        char *full = index_and_list(tmp, "full.db");
        cbm_unsetenv("CBM_TEST_SQL_FULL_PARSE_ON");
        th_rmtree(tmp);
        ASSERT_NOT_NULL(cut);
        ASSERT_NOT_NULL(full);
        /* Not vacuous: the tables, the view and its lineage are there. */
        ASSERT_NOT_NULL(strstr(cut, "Table|city|"));
        ASSERT_NOT_NULL(strstr(cut, "View|big_cities|"));
        ASSERT_NOT_NULL(strstr(cut, "USAGE|"));
        if (esc == 0 && strcmp(cut, full) != 0) {
            fprintf(stderr, "--- cut ---\n%s--- full ---\n%s", cut, full);
        }
        if (esc == 0) {
            ASSERT_STR_EQ(cut, full);
        } else {
            ASSERT_TRUE(listing_lines_within(full, cut));
        }
        free(cut);
        free(full);
    }
    PASS();
}

/* Spilling must be invisible in the OUTPUT: the same repository indexed with
 * results parked on disk must produce the same graph as one indexed entirely in
 * memory. It did not. The namespace map that `use`/`using`/package imports
 * resolve through was built from the in-memory result cache, where a PARKED
 * result is NULL, so every spilled file contributed no namespace and its
 * imports fell through to the looser fallback. Measured on the php corpus
 * (2026-09-18, reproducible 3/3 each way, and present on main): 57,182 edges in
 * memory against 59,379 while spilling — differing in BOTH directions, because
 * a file missing from that map does not fail to resolve, it resolves
 * differently.
 *
 * Why this needs its own fixture: test_parallel's spill-parity test uses the
 * compact parity harness, which omits the production pass that builds the map,
 * and its repo is Go+Java — neither reaches the namespace path. This one runs
 * the REAL pipeline over >MIN_FILES_FOR_PARALLEL files so the parallel route is
 * taken, with namespaced PHP that imports across files. */
TEST(pipeline_spill_resolves_namespace_imports_like_memory) {
    char tmp[256];
    snprintf(tmp, sizeof(tmp), "/tmp/cbm_spill_ns_XXXXXX");
    ASSERT_NOT_NULL(cbm_mkdtemp(tmp));

    /* 60 modules: each declares a namespace and the next one imports it, so
     * every file both contributes to the namespace map and depends on it. */
    enum { NS_FILES = 60 };
    for (int i = 0; i < NS_FILES; i++) {
        char name[64];
        char body[512];
        snprintf(name, sizeof(name), "Mod%02d.php", i);
        snprintf(body, sizeof(body),
                 "<?php\nnamespace App\\Mod%02d;\n\nuse App\\Mod%02d\\Thing%02d;\n\n"
                 "class Thing%02d {\n"
                 "    public function run() { $t = new Thing%02d(); return $t->run(); }\n}\n",
                 i, (i + 1) % NS_FILES, (i + 1) % NS_FILES, i, (i + 1) % NS_FILES);
        write_temp_file(tmp, name, body);
    }

    int counts[2] = {0, 0};
    int imports[2] = {0, 0};
    for (int pass = 0; pass < 2; pass++) {
        char db_path[512];
        snprintf(db_path, sizeof(db_path), "%s/ns%d.db", tmp, pass);
        if (pass == 1) {
            cbm_setenv("CBM_MEM_SPILL", "1", 1); /* park every result on disk */
        }
        cbm_pipeline_t *p = cbm_pipeline_new(tmp, db_path, CBM_MODE_FULL);
        ASSERT_NOT_NULL(p);
        int rc = cbm_pipeline_run(p);
        if (pass == 1) {
            cbm_unsetenv("CBM_MEM_SPILL");
        }
        ASSERT_EQ(rc, 0);
        cbm_store_t *s = cbm_store_open_path(db_path);
        ASSERT_NOT_NULL(s);
        const char *project = cbm_pipeline_project_name(p);
        counts[pass] = cbm_store_count_edges(s, project);
        imports[pass] = cbm_store_count_edges_by_type(s, project, "IMPORTS");
        cbm_store_close(s);
        cbm_pipeline_free(p);
    }
    th_rmtree(tmp);

    /* The imports must actually have resolved, or this compares 0 == 0. */
    ASSERT_GT(imports[0], 0);
    ASSERT_EQ(imports[0], imports[1]);
    ASSERT_EQ(counts[0], counts[1]);
    PASS();
}

/* ── Integration: structure pass on temp repo ────────────────────── */

TEST(pipeline_structure_nodes) {
    if (setup_test_repo() != 0) {
        FAIL("failed to create temp dir");
    }

    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/test.db", g_tmpdir);

    cbm_pipeline_t *p = cbm_pipeline_new(g_tmpdir, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);

    int rc = cbm_pipeline_run(p);
    ASSERT_EQ(rc, 0);

    /* Verify results by opening the store */
    cbm_store_t *s = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s);

    const char *project = cbm_pipeline_project_name(p);

    /* Should have nodes: 1 Project + 2 Folders + 3 Files + N Functions */
    int node_count = cbm_store_count_nodes(s, project);
    ASSERT_GTE(node_count, 9); /* 6 structure + at least 3 definitions */

    /* Verify project node exists */
    cbm_node_t proj_node = {0};
    rc = cbm_store_find_node_by_qn(s, project, project, &proj_node);
    ASSERT_EQ(rc, CBM_STORE_OK);
    ASSERT_STR_EQ(proj_node.label, "Project");
    cbm_node_free_fields(&proj_node);

    /* Verify folder nodes */
    cbm_node_t *folders = NULL;
    int folder_count = 0;
    rc = cbm_store_find_nodes_by_label(s, project, "Folder", &folders, &folder_count);
    ASSERT_EQ(rc, CBM_STORE_OK);
    ASSERT_GTE(folder_count, 2); /* pkg, pkg/util */
    cbm_store_free_nodes(folders, folder_count);

    /* Verify file nodes */
    cbm_node_t *file_nodes = NULL;
    int file_count = 0;
    rc = cbm_store_find_nodes_by_label(s, project, "File", &file_nodes, &file_count);
    ASSERT_EQ(rc, CBM_STORE_OK);
    ASSERT_GTE(file_count, 3); /* main.go, service.go, helper.go */
    cbm_store_free_nodes(file_nodes, file_count);

    /* Verify edges exist */
    int edge_count = cbm_store_count_edges(s, project);
    ASSERT_GTE(edge_count, 5); /* CONTAINS_FOLDER + CONTAINS_FILE edges */

    cbm_store_close(s);
    cbm_pipeline_free(p);
    teardown_test_repo();
    PASS();
}

/* Number of `label` nodes whose file_path starts with `prefix`, or -1. */
static int count_nodes_with_path_prefix(cbm_store_t *s, const char *project, const char *label,
                                        const char *prefix) {
    cbm_node_t *nodes = NULL;
    int count = 0;
    if (cbm_store_find_nodes_by_label(s, project, label, &nodes, &count) != CBM_STORE_OK) {
        return -1;
    }
    int hits = 0;
    for (int i = 0; i < count; i++) {
        if (nodes[i].file_path && strncmp(nodes[i].file_path, prefix, strlen(prefix)) == 0) {
            hits++;
        }
    }
    cbm_store_free_nodes(nodes, count);
    return hits;
}

/* Make-style dep-info .d files are dropped at discovery, so the graph holds no
 * File or Module node for them and no Folder for a directory that held only
 * dep-info. Real D source beside a dep-info file keeps its nodes and folder. */
TEST(pipeline_d_dep_info_leaves_no_nodes) {
    char tmp[256];
    snprintf(tmp, sizeof(tmp), "/tmp/cbm_dotd_graph_XXXXXX");
    ASSERT_NOT_NULL(cbm_mkdtemp(tmp));
    char repo[512];
    snprintf(repo, sizeof(repo), "%s/repo", tmp);
    write_temp_file(repo, "cargo-target/debug/deps/app-0123abcd.d",
                    "/r/cargo-target/debug/deps/app-0123abcd.d: src/main.rs\n\nsrc/main.rs:\n");
    write_temp_file(repo, "src/app.d", "module app;\n\nvoid main() {}\n");
    write_temp_file(repo, "src/app.o.d", "src/app.o: src/app.d\n");

    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/test.db", tmp);
    cbm_pipeline_t *p = cbm_pipeline_new(repo, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    ASSERT_EQ(cbm_pipeline_run(p), 0);
    cbm_store_t *s = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s);
    const char *project = cbm_pipeline_project_name(p);

    int dep_folders = count_nodes_with_path_prefix(s, project, "Folder", "cargo-target");
    int dep_files = count_nodes_with_path_prefix(s, project, "File", "cargo-target");
    int dep_modules = count_nodes_with_path_prefix(s, project, "Module", "cargo-target");
    int obj_files = count_nodes_with_path_prefix(s, project, "File", "src/app.o.d");
    int obj_modules = count_nodes_with_path_prefix(s, project, "Module", "src/app.o.d");
    int src_folders = count_nodes_with_path_prefix(s, project, "Folder", "src");
    int src_files = count_nodes_with_path_prefix(s, project, "File", "src/app.d");
    int src_modules = count_nodes_with_path_prefix(s, project, "Module", "src/app.d");

    cbm_store_close(s);
    cbm_pipeline_free(p);
    th_rmtree(tmp);

    ASSERT_EQ(dep_folders, 0);
    ASSERT_EQ(dep_files, 0);
    ASSERT_EQ(dep_modules, 0);
    ASSERT_EQ(obj_files, 0);
    ASSERT_EQ(obj_modules, 0);
    ASSERT_EQ(src_folders, 1);
    ASSERT_EQ(src_files, 1);
    ASSERT_EQ(src_modules, 1);
    PASS();
}

/* Issue #516: an ADR stored via manage_adr (project_summaries) must survive a
 * full re-index. A full re-index deletes the DB and rebuilds it from the graph
 * buffer, which writes an empty project_summaries table; the fix captures the
 * ADR before the delete and restores it after the rebuild. Reproduce-first:
 * index, store an ADR, force a full re-index by adding files, assert the ADR
 * is still present and unchanged. */
/* #1665: a persistence artifact export failure must not be reported as a
 * repo_path problem. Create the artifact directory as a regular FILE so
 * cbm_mkdir_p(.codebase-memory) fails deterministically (works as root too),
 * run with persistence enabled, and assert: the run fails, the DB was
 * published (publish happens before export), the pipeline snapshots the export
 * error, and a clean re-run leaves the snapshot empty. */
TEST(pipeline_export_error_snapshot_on_artifact_failure) {
    char tmp[256];
    snprintf(tmp, sizeof(tmp), "/tmp/cbm_export1665_XXXXXX");
    if (!cbm_mkdtemp(tmp)) {
        FAIL("failed to create temp dir");
    }

    char path[512];
    snprintf(path, sizeof(path), "%s/main.py", tmp);
    FILE *f = fopen(path, "w");
    ASSERT_NOT_NULL(f);
    fprintf(f, "def foo():\n    pass\n");
    fclose(f);

    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/test.db", tmp);

    /* Block the artifact directory: a FILE at .codebase-memory makes the
     * export's mkdir_p fail with a deterministic error on every platform. */
    char art_block[512];
    snprintf(art_block, sizeof(art_block), "%s/.codebase-memory", tmp);
    f = fopen(art_block, "w");
    ASSERT_NOT_NULL(f);
    fprintf(f, "block\n");
    fclose(f);

    cbm_pipeline_t *p = cbm_pipeline_new(tmp, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    cbm_pipeline_set_persistence(p, true);

    int rc = cbm_pipeline_run(p);
    ASSERT_NEQ(rc, 0);

    /* The export runs after publish, so the DB must exist despite the failure. */
    struct stat db_st;
    ASSERT_EQ(stat(db_path, &db_st), 0);

    const char *export_error = cbm_pipeline_export_error(p);
    ASSERT_NOT_NULL(export_error);
    ASSERT_TRUE(export_error[0] != '\0');
    ASSERT_NOT_NULL(strstr(export_error, "prepare_artifact_dir"));
    cbm_pipeline_free(p);

    /* Control: remove the blocker; a fresh run succeeds and leaves no snapshot. */
    (void)cbm_unlink(art_block);
    cbm_pipeline_t *p2 = cbm_pipeline_new(tmp, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p2);
    cbm_pipeline_set_persistence(p2, true);
    rc = cbm_pipeline_run(p2);
    ASSERT_EQ(rc, 0);
    const char *export_error2 = cbm_pipeline_export_error(p2);
    ASSERT_NOT_NULL(export_error2);
    ASSERT_TRUE(export_error2[0] == '\0');
    cbm_pipeline_free(p2);

    rm_rf(tmp);
    PASS();
}

TEST(pipeline_adr_survives_full_reindex) {
    char tmp[256];
    snprintf(tmp, sizeof(tmp), "/tmp/cbm_adr_XXXXXX");
    if (!cbm_mkdtemp(tmp)) {
        FAIL("failed to create temp dir");
    }

    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/test.db", tmp);

    /* Initial index with a single source file. */
    char path[512];
    snprintf(path, sizeof(path), "%s/main.py", tmp);
    FILE *f = fopen(path, "w");
    ASSERT_NOT_NULL(f);
    fprintf(f, "def foo():\n    pass\n");
    fclose(f);

    cbm_pipeline_t *p1 = cbm_pipeline_new(tmp, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p1);
    ASSERT_EQ(cbm_pipeline_run(p1), 0);
    const char *project = cbm_pipeline_project_name(p1);
    char project_copy[256];
    snprintf(project_copy, sizeof(project_copy), "%s", project);
    cbm_pipeline_free(p1);

    /* Store an ADR. */
    const char *adr_text = "# Decision\nWe chose X over Y.";
    cbm_store_t *s1 = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s1);
    ASSERT_EQ(cbm_store_adr_store(s1, project_copy, adr_text), CBM_STORE_OK);
    cbm_store_close(s1);

    /* Force a full re-index: add enough files to exceed the incremental
     * threshold so the DB is deleted and rebuilt. */
    for (int i = 0; i < 4; i++) {
        snprintf(path, sizeof(path), "%s/extra%d.py", tmp, i);
        f = fopen(path, "w");
        ASSERT_NOT_NULL(f);
        fprintf(f, "def g%d():\n    return %d\n", i, i);
        fclose(f);
    }

    cbm_pipeline_t *p2 = cbm_pipeline_new(tmp, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p2);
    ASSERT_EQ(cbm_pipeline_run(p2), 0);
    cbm_pipeline_free(p2);

    /* The ADR must still be present and unchanged. */
    cbm_store_t *s2 = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s2);
    cbm_adr_t adr = {0};
    int rc = cbm_store_adr_get(s2, project_copy, &adr);
    ASSERT_EQ(rc, CBM_STORE_OK);
    ASSERT_NOT_NULL(adr.content);
    ASSERT_STR_EQ(adr.content, adr_text);
    cbm_store_adr_free(&adr);
    cbm_store_close(s2);

    rm_rf(tmp);
    PASS();
}

static int pipeline_unresolved_review_case(int padding, bool spill) {
    char tmp[256] = "/tmp/cbm_unresolved_review_XXXXXX";
    ASSERT_NOT_NULL(cbm_mkdtemp(tmp));
    char db[512], path[512];
    const char *names[] = {"cliente.js", "servicio.js", "ayudante.js",
                           "directo.js", "missing.js",  "route.js"};
    const char *sources[] = {
        "export function crearCliente() { function buscar(id) { return id; } return { buscar }; "
        "}\n",
        "export function crearServicio({ cliente }) {\n"
        "  function procesar(id) {\n"
        "    cliente.buscar(id); return cliente.buscar(id + 1);\n"
        "  }\n  return { procesar };\n}\n",
        "export function ayudante(id) { return id; }\n",
        "import { ayudante } from './ayudante.js';\n"
        "export function usarDirecto(id) { ayudante(id); return ayudante(id + 1); }\n",
        "import { absent } from './ayudante.js';\n"
        "export function missing(id) { return absent(id); }\n",
        "export function setup({ app }) { app.get('/x', handler); }\n"
        "function handler() { return 1; }\n"};
    for (size_t i = 0; i < sizeof(names) / sizeof(names[0]); i++) {
        snprintf(path, sizeof(path), "%s/%s", tmp, names[i]);
        FILE *f = fopen(path, "w");
        ASSERT_NOT_NULL(f);
        fputs(sources[i], f);
        fclose(f);
    }
    for (int i = 0; i < padding; i++) {
        snprintf(path, sizeof(path), "%s/pad%d.js", tmp, i);
        FILE *f = fopen(path, "w");
        ASSERT_NOT_NULL(f);
        fprintf(f, "export function pad%d() { return %d; }\n", i, i);
        fclose(f);
    }
    snprintf(db, sizeof(db), "%s/index.db", tmp);
    if (spill)
        cbm_setenv("CBM_MEM_SPILL", "1", 1);
    cbm_pipeline_t *p = cbm_pipeline_new(tmp, db, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    int rc = cbm_pipeline_run(p);
    if (spill)
        cbm_unsetenv("CBM_MEM_SPILL");
    ASSERT_EQ(rc, 0);
    char project[256];
    snprintf(project, sizeof(project), "%s", cbm_pipeline_project_name(p));
    cbm_pipeline_free(p);
    cbm_store_t *st = cbm_store_open_path(db);
    ASSERT_NOT_NULL(st);
    cbm_coverage_row_t *rows = NULL;
    int count = 0;
    ASSERT_EQ(cbm_store_coverage_get_path(st, project, "directo.js", &rows, &count), CBM_STORE_OK);
    for (int i = 0; i < count; i++)
        ASSERT_FALSE(strcmp(rows[i].kind, "unresolved_calls") == 0);
    cbm_store_free_coverage(rows, count);
    rows = NULL;
    count = 0;
    ASSERT_EQ(cbm_store_coverage_get_path(st, project, "route.js", &rows, &count), CBM_STORE_OK);
    for (int i = 0; i < count; i++)
        ASSERT_FALSE(strcmp(rows[i].kind, "unresolved_calls") == 0);
    cbm_store_free_coverage(rows, count);
    rows = NULL;
    count = 0;
    ASSERT_EQ(cbm_store_coverage_get_path(st, project, "servicio.js", &rows, &count), CBM_STORE_OK);
    ASSERT_EQ(count, 1);
    yyjson_doc *doc = yyjson_read(rows[0].detail, strlen(rows[0].detail), 0);
    ASSERT_NOT_NULL(doc);
    yyjson_val *sites = yyjson_doc_get_root(doc);
    ASSERT_EQ(yyjson_arr_size(sites), 2);
    for (size_t i = 0; i < 2; i++) {
        yyjson_val *site = yyjson_arr_get(sites, i);
        const char *caller = yyjson_get_str(yyjson_obj_get(site, "caller"));
        ASSERT_NOT_NULL(caller);
        ASSERT_NOT_NULL(strstr(caller, ".procesar"));
        ASSERT_EQ(yyjson_get_int(yyjson_obj_get(site, "line")), 3);
        ASSERT_NOT_NULL(yyjson_get_str(yyjson_obj_get(site, "candidate")));
    }
    yyjson_doc_free(doc);
    cbm_store_free_coverage(rows, count);
    rows = NULL;
    count = 0;
    ASSERT_EQ(cbm_store_coverage_get_path(st, project, "missing.js", &rows, &count), CBM_STORE_OK);
    ASSERT_EQ(count, 1);
    doc = yyjson_read(rows[0].detail, strlen(rows[0].detail), 0);
    ASSERT_NOT_NULL(doc);
    ASSERT_EQ(yyjson_arr_size(yyjson_doc_get_root(doc)), 1);
    yyjson_doc_free(doc);
    cbm_store_free_coverage(rows, count);
    cbm_store_close(st);
    rm_rf(tmp);
    PASS();
}

/* A noisy semantic resolver must retain an explicit bounded-coverage marker,
 * including when a single reason would exceed the entire detail budget. */
TEST(pipeline_unresolved_capture_bounds_count_and_json_bytes) {
    char tmp[256] = "/tmp/cbm_unresolved_cap_XXXXXX";
    ASSERT_NOT_NULL(cbm_mkdtemp(tmp));
    char db[512];
    snprintf(db, sizeof(db), "%s/index.db", tmp);
    cbm_pipeline_t *p = cbm_pipeline_new(tmp, db, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    CBMResolvedCall *sites = calloc(1001, sizeof(*sites));
    ASSERT_NOT_NULL(sites);
    for (int i = 0; i < 1001; i++) {
        sites[i] = (CBMResolvedCall){.kind = CBM_RESOLVED_INVOCATION,
                                     .caller_qn = "cap.run",
                                     .callee_qn = "missing",
                                     .strategy = "lsp_unresolved",
                                     .site_start_byte = (uint32_t)i * 2,
                                     .site_end_byte = (uint32_t)i * 2 + 1};
    }
    CBMFileResult result = {.resolved_calls = {.items = sites, .count = 1001}};
    cbm_pipeline_record_unresolved_calls(p, "many.js", &result, NULL);
    cbm_coverage_row_t *rows = NULL;
    int count = 0;
    bool complete = false;
    cbm_pipeline_get_unresolved_calls(p, &rows, &count, &complete);
    ASSERT_TRUE(complete);
    ASSERT_EQ(count, 1);
    ASSERT_TRUE(strlen(rows[0].detail) <= 128 * 1024);
    yyjson_doc *doc = yyjson_read(rows[0].detail, strlen(rows[0].detail), 0);
    ASSERT_NOT_NULL(doc);
    yyjson_val *array = yyjson_doc_get_root(doc);
    ASSERT_TRUE(yyjson_arr_size(array) <= 1001);
    ASSERT_TRUE(yyjson_get_bool(yyjson_obj_get(yyjson_arr_get_last(array), "truncated")));
    yyjson_doc_free(doc);

    char *reason = malloc(200000);
    ASSERT_NOT_NULL(reason);
    memset(reason, '"', 199999);
    reason[199999] = '\0';
    sites[0].reason = reason;
    result.resolved_calls.count = 1;
    cbm_pipeline_record_unresolved_calls(p, "huge.js", &result, NULL);
    cbm_pipeline_get_unresolved_calls(p, &rows, &count, &complete);
    ASSERT_TRUE(complete);
    ASSERT_EQ(count, 2);
    ASSERT_TRUE(strlen(rows[1].detail) <= 128 * 1024);
    doc = yyjson_read(rows[1].detail, strlen(rows[1].detail), 0);
    ASSERT_NOT_NULL(doc);
    array = yyjson_doc_get_root(doc);
    ASSERT_EQ(yyjson_arr_size(array), 1);
    ASSERT_TRUE(yyjson_get_bool(yyjson_obj_get(yyjson_arr_get_last(array), "truncated")));
    yyjson_doc_free(doc);
    free(reason);
    free(sites);
    cbm_pipeline_free(p);
    rm_rf(tmp);
    PASS();
}

TEST(pipeline_unresolved_review_sequential) {
    return pipeline_unresolved_review_case(0, false);
}
TEST(pipeline_unresolved_review_parallel) {
    return pipeline_unresolved_review_case(55, false);
}
TEST(pipeline_unresolved_review_spill) {
    return pipeline_unresolved_review_case(55, true);
}

TEST(pipeline_records_unresolved_injected_call_sites) {
    char tmp[256] = "/tmp/cbm_unresolved_calls_XXXXXX";
    ASSERT_NOT_NULL(cbm_mkdtemp(tmp));
    char db_path[512], path[512];
    snprintf(db_path, sizeof(db_path), "%s/test.db", tmp);
    snprintf(path, sizeof(path), "%s/cliente.js", tmp);
    FILE *f = fopen(path, "w");
    ASSERT_NOT_NULL(f);
    fputs("export function crearCliente() { function buscar(id) { return id; } "
          "return { buscar }; }\n",
          f);
    fclose(f);
    snprintf(path, sizeof(path), "%s/servicio.js", tmp);
    f = fopen(path, "w");
    ASSERT_NOT_NULL(f);
    fputs("export function crearServicio({ cliente }) {\n"
          "  function procesar(id) { return cliente.buscar(id); }\n"
          "  return { procesar };\n}\n",
          f);
    fclose(f);

    cbm_pipeline_t *p = cbm_pipeline_new(tmp, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    ASSERT_EQ(cbm_pipeline_run(p), 0);
    char project[256];
    snprintf(project, sizeof(project), "%s", cbm_pipeline_project_name(p));
    cbm_pipeline_free(p);
    cbm_store_t *st = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(st);
    cbm_coverage_row_t *rows = NULL;
    int count = 0;
    ASSERT_EQ(cbm_store_coverage_get_path(st, project, "servicio.js", &rows, &count), CBM_STORE_OK);
    bool found = false;
    for (int i = 0; i < count; i++) {
        if (strcmp(rows[i].kind, "unresolved_calls") == 0 && strstr(rows[i].detail, "buscar") &&
            strstr(rows[i].detail, "method_not_in_registry")) {
            found = true;
        }
    }
    ASSERT_TRUE(found);
    cbm_store_free_coverage(rows, count);
    cbm_store_close(st);

    /* Reindexing another file must retain this file's diagnostic. */
    snprintf(path, sizeof(path), "%s/cliente.js", tmp);
    f = fopen(path, "a");
    ASSERT_NOT_NULL(f);
    fputs("\n// unrelated edit\n", f);
    fclose(f);
    p = cbm_pipeline_new(tmp, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    ASSERT_EQ(cbm_pipeline_run(p), 0);
    cbm_pipeline_free(p);
    st = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(st);
    rows = NULL;
    count = 0;
    ASSERT_EQ(cbm_store_coverage_get_path(st, project, "servicio.js", &rows, &count), CBM_STORE_OK);
    found = false;
    for (int i = 0; i < count; i++) {
        found |= strcmp(rows[i].kind, "unresolved_calls") == 0;
    }
    ASSERT_TRUE(found);
    cbm_store_free_coverage(rows, count);
    cbm_store_close(st);

    /* The edited file must lose its old diagnostic on the next generation. */
    snprintf(path, sizeof(path), "%s/servicio.js", tmp);
    f = fopen(path, "w");
    ASSERT_NOT_NULL(f);
    fputs(
        "export function crearServicio({ cliente }) { return { procesar(id) { return id; } }; }\n",
        f);
    fclose(f);
    p = cbm_pipeline_new(tmp, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    ASSERT_EQ(cbm_pipeline_run(p), 0);
    cbm_pipeline_free(p);
    st = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(st);
    rows = NULL;
    count = 0;
    ASSERT_EQ(cbm_store_coverage_get_path(st, project, "servicio.js", &rows, &count), CBM_STORE_OK);
    for (int i = 0; i < count; i++) {
        ASSERT_FALSE(strcmp(rows[i].kind, "unresolved_calls") == 0);
    }
    cbm_store_free_coverage(rows, count);
    cbm_store_close(st);
    rm_rf(tmp);
    PASS();
}

TEST(pipeline_structure_edges) {
    if (setup_test_repo() != 0) {
        FAIL("failed to create temp dir");
    }

    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/test.db", g_tmpdir);

    cbm_pipeline_t *p = cbm_pipeline_new(g_tmpdir, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    int rc = cbm_pipeline_run(p);
    ASSERT_EQ(rc, 0);

    cbm_store_t *s = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s);
    const char *project = cbm_pipeline_project_name(p);

    /* Check CONTAINS_FILE edges */
    int cf_count = cbm_store_count_edges_by_type(s, project, "CONTAINS_FILE");
    /* Check CONTAINS_FOLDER edges */
    int cd_count = cbm_store_count_edges_by_type(s, project, "CONTAINS_FOLDER");

    /* Cleanup before assertions (so failures don't leak) */
    cbm_store_close(s);
    cbm_pipeline_free(p);
    teardown_test_repo();

    ASSERT_GTE(cf_count, 3); /* project->main.go, pkg->service.go, util->helper.go */
    ASSERT_GTE(cd_count, 1); /* project->pkg (pkg->util may merge on some platforms) */
    PASS();
}

TEST(pipeline_branch_root_structure) {
    if (setup_test_repo() != 0) {
        FAIL("failed to create temp dir");
    }

    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/test_branch_root.db", g_tmpdir);

    cbm_pipeline_t *p = cbm_pipeline_new(g_tmpdir, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    int rc = cbm_pipeline_run(p);
    ASSERT_EQ(rc, 0);

    cbm_store_t *s = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s);
    const char *project = cbm_pipeline_project_name(p);

    char branch_qn[1024];
    snprintf(branch_qn, sizeof(branch_qn), "%s.__branch__.working-tree", project);

    cbm_node_t project_node = {0};
    cbm_node_t branch_node = {0};
    cbm_node_t root_file_node = {0};
    cbm_node_t root_folder_node = {0};
    rc = cbm_store_find_node_by_qn(s, project, project, &project_node);
    ASSERT_EQ(rc, CBM_STORE_OK);
    rc = cbm_store_find_node_by_qn(s, project, branch_qn, &branch_node);
    ASSERT_EQ(rc, CBM_STORE_OK);
    ASSERT_STR_EQ(branch_node.label, "Branch");
    ASSERT_STR_EQ(branch_node.name, "working-tree");
    ASSERT_NOT_NULL(strstr(branch_node.properties_json, "\"is_git\":false"));
    char *root_folder_qn = cbm_pipeline_fqn_folder(project, "pkg");
    char *root_file_qn = cbm_pipeline_fqn_compute(project, "main.go", "__file__");
    ASSERT_NOT_NULL(root_folder_qn);
    ASSERT_NOT_NULL(root_file_qn);
    rc = cbm_store_find_node_by_qn(s, project, root_folder_qn, &root_folder_node);
    ASSERT_EQ(rc, CBM_STORE_OK);
    rc = cbm_store_find_node_by_qn(s, project, root_file_qn, &root_file_node);
    ASSERT_EQ(rc, CBM_STORE_OK);

    cbm_edge_t *has_branch = NULL;
    int has_branch_count = 0;
    rc = cbm_store_find_edges_by_source_type(s, project_node.id, "HAS_BRANCH", &has_branch,
                                             &has_branch_count);
    ASSERT_EQ(rc, CBM_STORE_OK);
    ASSERT_EQ(has_branch_count, 1);
    ASSERT_EQ(has_branch[0].target_id, branch_node.id);

    cbm_edge_t *project_files = NULL;
    int project_file_count = 0;
    rc = cbm_store_find_edges_by_source_type(s, project_node.id, "CONTAINS_FILE", &project_files,
                                             &project_file_count);
    ASSERT_EQ(rc, CBM_STORE_OK);
    ASSERT_EQ(project_file_count, 0);

    cbm_edge_t *branch_files = NULL;
    int branch_file_count = 0;
    rc = cbm_store_find_edges_by_source_type(s, branch_node.id, "CONTAINS_FILE", &branch_files,
                                             &branch_file_count);
    ASSERT_EQ(rc, CBM_STORE_OK);
    ASSERT_EQ(branch_file_count, 1);
    ASSERT_EQ(branch_files[0].target_id, root_file_node.id);

    cbm_edge_t *branch_folders = NULL;
    int branch_folder_count = 0;
    rc = cbm_store_find_edges_by_source_type(s, branch_node.id, "CONTAINS_FOLDER", &branch_folders,
                                             &branch_folder_count);
    ASSERT_EQ(rc, CBM_STORE_OK);
    ASSERT_EQ(branch_folder_count, 1);
    ASSERT_EQ(branch_folders[0].target_id, root_folder_node.id);

    cbm_store_free_edges(has_branch, has_branch_count);
    cbm_store_free_edges(project_files, project_file_count);
    cbm_store_free_edges(branch_files, branch_file_count);
    cbm_store_free_edges(branch_folders, branch_folder_count);
    cbm_node_free_fields(&project_node);
    cbm_node_free_fields(&branch_node);
    cbm_node_free_fields(&root_file_node);
    cbm_node_free_fields(&root_folder_node);
    free(root_folder_qn);
    free(root_file_qn);
    cbm_store_close(s);
    cbm_pipeline_free(p);
    teardown_test_repo();
    PASS();
}

