/* True iff a CALLS edge exists from a node named src_name to a node named
 * tgt_name. Used to assert cross-file call resolution survives a reindex. */
static bool cross_file_edge_exists(cbm_store_t *s, const char *project, const char *src_name,
                                   const char *tgt_name, const char *edge_type) {
    cbm_node_t *srcs = NULL;
    cbm_node_t *tgts = NULL;
    int sc = 0;
    int tc = 0;
    cbm_store_find_nodes_by_name(s, project, src_name, &srcs, &sc);
    cbm_store_find_nodes_by_name(s, project, tgt_name, &tgts, &tc);
    bool found = false;
    for (int i = 0; i < sc && !found; i++) {
        cbm_edge_t *edges = NULL;
        int ec = 0;
        cbm_store_find_edges_by_source_type(s, srcs[i].id, edge_type, &edges, &ec);
        for (int j = 0; j < ec && !found; j++) {
            for (int k = 0; k < tc; k++) {
                if (edges[j].target_id == tgts[k].id) {
                    found = true;
                    break;
                }
            }
        }
        if (edges) {
            cbm_store_free_edges(edges, ec);
        }
    }
    if (srcs) {
        cbm_store_free_nodes(srcs, sc);
    }
    if (tgts) {
        cbm_store_free_nodes(tgts, tc);
    }
    return found;
}

static bool cross_file_call_exists(cbm_store_t *s, const char *project, const char *src_name,
                                   const char *tgt_name) {
    return cross_file_edge_exists(s, project, src_name, tgt_name, "CALLS");
}

/* True iff the exact named CALLS edge exists and its serialized strategy
 * contains `strategy_fragment`. Parallel synthetic-carrier regressions use
 * this on a separate ordinary-call control: it proves the cross-file LSP ran
 * successfully for the language/target, rather than letting a registry-only
 * edge make a broken fixture look healthy. */
static bool cross_file_call_has_strategy(cbm_store_t *s, const char *project, const char *src_name,
                                         const char *tgt_name, const char *strategy_fragment) {
    cbm_node_t *srcs = NULL;
    cbm_node_t *tgts = NULL;
    int sc = 0;
    int tc = 0;
    cbm_store_find_nodes_by_name(s, project, src_name, &srcs, &sc);
    cbm_store_find_nodes_by_name(s, project, tgt_name, &tgts, &tc);
    bool found = false;
    for (int i = 0; i < sc && !found; i++) {
        cbm_edge_t *edges = NULL;
        int ec = 0;
        cbm_store_find_edges_by_source_type(s, srcs[i].id, "CALLS", &edges, &ec);
        for (int j = 0; j < ec && !found; j++) {
            for (int k = 0; k < tc; k++) {
                if (edges[j].target_id == tgts[k].id && edges[j].properties_json &&
                    strstr(edges[j].properties_json, strategy_fragment)) {
                    found = true;
                    break;
                }
            }
        }
        if (edges) {
            cbm_store_free_edges(edges, ec);
        }
    }
    if (srcs) {
        cbm_store_free_nodes(srcs, sc);
    }
    if (tgts) {
        cbm_store_free_nodes(tgts, tc);
    }
    return found;
}

/* Nix attrpath qualification, end to end. A call inside a scoped binding must
 * source to the QUALIFIED definition.
 *
 * This has to be a pipeline test rather than an extraction one. Definition QNs
 * (extract_defs.c) and call-scope QNs (extract_unified.c) are computed by two
 * separate functions. If they disagree by even one segment, the CALLS edge names
 * a source node that was never minted and is dropped at write — with no error,
 * and with every extraction-level assertion still passing. Only the store sees it.
 *
 * Both callers below are scoped, one by an enclosing attrset and one by a dotted
 * attrpath, so this covers both routes into the qualified name. */
TEST(pipeline_nix_scoped_binding_calls_resolve) {
    if (setup_test_repo() != 0) {
        FAIL("failed to create temp dir");
    }

    char nix_path[512];
    snprintf(nix_path, sizeof(nix_path), "%s/lib.nix", g_tmpdir);
    FILE *nf = fopen(nix_path, "w");
    if (!nf) {
        teardown_test_repo();
        FAIL("failed to write nix fixture");
    }
    fprintf(nf, "{ prelude }:\n"
                "let\n"
                "  nixTarget = t: t + 1;\n"
                "in\n"
                "{\n"
                "  setA = { nixCaller = x: nixTarget x; };\n"
                "  outer.inner.nixDeepCaller = y: nixTarget y;\n"
                "}\n");
    fclose(nf);

    char nix_db[512];
    snprintf(nix_db, sizeof(nix_db), "%s/test_nix_calls.db", g_tmpdir);

    cbm_pipeline_t *np = cbm_pipeline_new(g_tmpdir, nix_db, CBM_MODE_FULL);
    ASSERT_NOT_NULL(np);
    ASSERT_EQ(cbm_pipeline_run(np), 0);

    cbm_store_t *ns = cbm_store_open_path(nix_db);
    ASSERT_NOT_NULL(ns);
    const char *nix_project = cbm_pipeline_project_name(np);

    /* Scoped by an enclosing attrset: the def QN is proj.lib.setA.nixCaller. */
    ASSERT(cross_file_call_exists(ns, nix_project, "nixCaller", "nixTarget"));
    /* Scoped by a dotted attrpath: proj.lib.outer.inner.nixDeepCaller. */
    ASSERT(cross_file_call_exists(ns, nix_project, "nixDeepCaller", "nixTarget"));

    cbm_store_close(ns);
    cbm_pipeline_free(np);
    teardown_test_repo();
    PASS();
}

/* Terraform reference resolution, end to end.
 *
 * An HCL block names itself with its labels appended -- find_hcl_block_name
 * mints "resource.aws_instance.web" -- and the module resolver
 * (pass_terraform.c) finds the block a reference `aws_instance.web.id` names
 * by recomputing that QN from the declaring file and the name. The reference
 * USAGEs it from the block holding it, `resource.aws_eip.ip`; the file itself
 * USAGEs nothing (a .tf file is no longer served by the generic by-name index).
 *
 * This has to be a pipeline test: the extractor mints the name and the
 * resolver recomputes the QN, so the two halves can disagree with every
 * extraction-level assertion still green.
 */
TEST(pipeline_hcl_block_reference_resolves_to_its_block) {
    if (setup_test_repo() != 0) {
        FAIL("failed to create temp dir");
    }

    char tf_path[512];
    snprintf(tf_path, sizeof(tf_path), "%s/main.tf", g_tmpdir);
    FILE *tf = fopen(tf_path, "w");
    if (!tf) {
        teardown_test_repo();
        FAIL("failed to write terraform fixture");
    }
    fprintf(tf, "resource \"aws_instance\" \"web\" {\n"
                "  ami           = \"ami-0c55b159cbfafe1f0\"\n"
                "  instance_type = \"t2.micro\"\n"
                "}\n"
                "\n"
                "resource \"aws_eip\" \"ip\" {\n"
                "  instance = aws_instance.web.id\n"
                "}\n");
    fclose(tf);

    char tf_db[512];
    snprintf(tf_db, sizeof(tf_db), "%s/test_hcl_refs.db", g_tmpdir);

    cbm_pipeline_t *tp = cbm_pipeline_new(g_tmpdir, tf_db, CBM_MODE_FULL);
    ASSERT_NOT_NULL(tp);
    ASSERT_EQ(cbm_pipeline_run(tp), 0);

    cbm_store_t *ts = cbm_store_open_path(tf_db);
    ASSERT_NOT_NULL(ts);
    const char *tf_project = cbm_pipeline_project_name(tp);

    ASSERT(cross_file_edge_exists(ts, tf_project, "resource.aws_eip.ip",
                                  "resource.aws_instance.web", "USAGE"));
    ASSERT(!cross_file_edge_exists(ts, tf_project, "main", "resource.aws_instance.web", "USAGE"));

    cbm_store_close(ts);
    cbm_pipeline_free(tp);
    teardown_test_repo();
    PASS();
}

/* Regression: incremental re-index of an edited file must NOT drop inbound
 * cross-file CALLS edges whose source lives in an UNCHANGED file.
 *
 * Repro: Serve() (pkg/service.go) CALLS Help() (pkg/util/helper.go). Editing
 * helper.go purges Help's node; before the fix the cascade deleted the
 * Serve->Help edge and never regenerated it (helper.go's callers are not
 * re-parsed), so the edge silently vanished on every edit and the incremental
 * graph diverged from a full reindex. */
TEST(pipeline_incremental_preserves_cross_file_calls) {
    if (setup_test_repo() != 0) {
        FAIL("failed to create temp dir");
    }

    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/test_incr_calls.db", g_tmpdir);

    /* 1. Full index. */
    cbm_pipeline_t *p1 = cbm_pipeline_new(g_tmpdir, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p1);
    ASSERT_EQ(cbm_pipeline_run(p1), 0);
    const char *project = cbm_pipeline_project_name(p1);

    cbm_store_t *s1 = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s1);
    int calls_before = cbm_store_count_edges_by_type(s1, project, "CALLS");
    ASSERT_GTE(calls_before, 2); /* main->Serve and Serve->Help at minimum */
    ASSERT_TRUE(cross_file_call_exists(s1, project, "Serve", "Help"));
    cbm_store_close(s1);
    cbm_pipeline_free(p1);

    /* 2. Edit the callee's file so the incremental classifier marks it changed
     *    (mtime+size differ). Help's symbol + qualified name are unchanged. */
    char helper[512];
    snprintf(helper, sizeof(helper), "%s/pkg/util/helper.go", g_tmpdir);
    ASSERT_EQ(th_append_file(helper, "\n// incremental regression marker\n"), 0);

    /* 3. Re-run on the SAME db_path → auto-routes to incremental re-index. */
    cbm_pipeline_t *p2 = cbm_pipeline_new(g_tmpdir, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p2);
    ASSERT_EQ(cbm_pipeline_run(p2), 0);

    /* 4. The inbound cross-file CALLS edge must survive and the total CALLS
     *    count must not regress. (Before the fix: Serve->Help is dropped.)
     *    NOTE: query with p2's project name — p1 (and the `project` pointer it
     *    owned) was freed above; p1 and p2 derive the same name from g_tmpdir. */
    const char *project2 = cbm_pipeline_project_name(p2);
    cbm_store_t *s2 = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s2);
    int calls_after = cbm_store_count_edges_by_type(s2, project2, "CALLS");
    ASSERT_EQ(calls_after, calls_before);
    ASSERT_TRUE(cross_file_call_exists(s2, project2, "Serve", "Help"));
    cbm_store_close(s2);
    cbm_pipeline_free(p2);

    teardown_test_repo();
    PASS();
}

static void write_temp_file(const char *dir, const char *name, const char *content);

/* An Ansible task file included by an UNCHANGED file is edited, its body
 * only. The includer is not re-parsed, so its IMPORTS edge must survive the
 * edited file's re-index: an edge into a node the repair re-creates would be
 * lost (the Terraform layer needed closure_terraform_decline for that). */
TEST(pipeline_incremental_keeps_ansible_includes_of_an_edited_file) {
    if (setup_test_repo() != 0) {
        FAIL("failed to create temp dir");
    }
    write_temp_file(g_tmpdir, "roles/app/tasks/main.yml",
                    "- name: setup\n  include_tasks: setup.yml\n");
    write_temp_file(g_tmpdir, "roles/app/tasks/setup.yml", "- name: s\n  debug:\n    msg: one\n");
    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/test_incr_ansible.db", g_tmpdir);

    cbm_pipeline_t *p1 = cbm_pipeline_new(g_tmpdir, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p1);
    ASSERT_EQ(cbm_pipeline_run(p1), 0);
    cbm_store_t *s1 = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s1);
    ASSERT_TRUE(cross_file_edge_exists(s1, cbm_pipeline_project_name(p1), "main.yml",
                                       "roles/app/tasks/setup.yml", "IMPORTS"));
    cbm_store_close(s1);
    cbm_pipeline_free(p1);

    write_temp_file(g_tmpdir, "roles/app/tasks/setup.yml",
                    "- name: s\n  debug:\n    msg: two words\n");

    cbm_pipeline_t *p2 = cbm_pipeline_new(g_tmpdir, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p2);
    ASSERT_EQ(cbm_pipeline_run(p2), 0);
    cbm_store_t *s2 = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s2);
    ASSERT_TRUE(cross_file_edge_exists(s2, cbm_pipeline_project_name(p2), "main.yml",
                                       "roles/app/tasks/setup.yml", "IMPORTS"));
    cbm_store_close(s2);
    cbm_pipeline_free(p2);

    teardown_test_repo();
    PASS();
}

/* The CALLS edges an Ansible notify draws (via notify); -1 on a query error. */
static int ansible_notify_calls(cbm_store_t *s, const char *project) {
    sqlite3_stmt *st = NULL;
    int n = -1;
    if (sqlite3_prepare_v2(cbm_store_get_db(s),
                           "SELECT COUNT(*) FROM edges WHERE project=?1 AND type='CALLS' AND "
                           "json_extract(properties,'$.via')='notify'",
                           -1, &st, NULL) == SQLITE_OK &&
        sqlite3_bind_text(st, 1, project, -1, SQLITE_TRANSIENT) == SQLITE_OK &&
        sqlite3_step(st) == SQLITE_ROW) {
        n = sqlite3_column_int(st, 0);
    }
    sqlite3_finalize(st);
    return n;
}

/* A task's notify CALLS the handlers of its role in another file. Editing
 * either file alone must land on the full graph: the handler file (a listen
 * topic renamed: one handler stops answering) re-creates its handlers, the
 * unchanged task file is not re-walked; the task file (a notifying task
 * added) is re-walked without the unchanged handler file. Both decline to
 * the full rebuild (closure_ansible_decline); the repair route kept a stale
 * edge in the first and lost every notify of the edited file in the second. */
TEST(pipeline_incremental_keeps_ansible_notifies_across_files) {
    if (setup_test_repo() != 0) {
        FAIL("failed to create temp dir");
    }
    write_temp_file(g_tmpdir, "roles/app/tasks/main.yml",
                    "- name: configure\n  command: /bin/true\n  notify: restart app\n");
    write_temp_file(g_tmpdir, "roles/app/handlers/main.yml",
                    "- name: h1\n  command: one\n  listen: restart app\n"
                    "- name: h2\n  command: two\n  listen: restart app\n");
    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/test_incr_notify.db", g_tmpdir);
    int want[] = {2, 1, 2};
    for (int step = 0; step < 3; step++) {
        if (step == 1) {
            write_temp_file(g_tmpdir, "roles/app/handlers/main.yml",
                            "- name: h1\n  command: one\n  listen: restart app\n"
                            "- name: h2\n  command: two\n  listen: something else\n");
        } else if (step == 2) {
            write_temp_file(g_tmpdir, "roles/app/tasks/main.yml",
                            "- name: configure\n  command: /bin/true\n  notify: restart app\n"
                            "- name: reconfigure\n  command: /bin/false\n  notify: restart app\n");
        }
        cbm_pipeline_t *p = cbm_pipeline_new(g_tmpdir, db_path, CBM_MODE_FULL);
        ASSERT_NOT_NULL(p);
        ASSERT_EQ(cbm_pipeline_run(p), 0);
        cbm_store_t *s = cbm_store_open_path(db_path);
        ASSERT_NOT_NULL(s);
        int calls = ansible_notify_calls(s, cbm_pipeline_project_name(p));
        cbm_store_close(s);
        cbm_pipeline_free(p);
        ASSERT_EQ(calls, want[step]);
    }
    teardown_test_repo();
    PASS();
}

/* The files Ansible tasks DEPLOY (via ansible), ordered, one per line, into
 * `out`; false on a query error. */
static bool ansible_deploy_targets(cbm_store_t *s, const char *project, char *out, size_t sz) {
    sqlite3_stmt *st = NULL;
    bool ok = false;
    if (sqlite3_prepare_v2(cbm_store_get_db(s),
                           "SELECT coalesce(group_concat(p, char(10)), '') FROM (SELECT "
                           "t.file_path AS p FROM edges e JOIN nodes t ON t.id=e.target_id WHERE "
                           "e.project=?1 AND e.type='DEPLOYS' AND "
                           "json_extract(e.properties,'$.via')='ansible' ORDER BY p)",
                           -1, &st, NULL) == SQLITE_OK &&
        sqlite3_bind_text(st, 1, project, -1, SQLITE_TRANSIENT) == SQLITE_OK &&
        sqlite3_step(st) == SQLITE_ROW) {
        snprintf(out, sz, "%s", (const char *)sqlite3_column_text(st, 0));
        ok = true;
    }
    sqlite3_finalize(st);
    return ok;
}

/* A kube task DEPLOYS the template its play rendered, read through a list of
 * the role's defaults/main.yml -- a file holding no task. Editing it (the
 * list names another template) or deleting it must land on the full graph,
 * and so must deleting the deployed template while a file of that name sits
 * in the task file's directory (the render falls back to it). The repair
 * did not re-walk the task file for the list edit -- it kept the edge to the
 * template the list no longer names -- and re-walked it for the deletion as
 * a dependent of the template, without the role's defaults: no edge at all.
 * Both decline to the full rebuild (closure_ansible_decline: a role's
 * defaults / vars; closure_ansible_dependent_decline: a task file joining
 * the repair as a dependent). A template body edit keeps the repair and the
 * edge. */
TEST(pipeline_incremental_keeps_ansible_deploys_across_files) {
    if (setup_test_repo() != 0) {
        FAIL("failed to create temp dir");
    }
    write_temp_file(g_tmpdir, "roles/app/tasks/main.yml",
                    "- name: Render\n  template:\n    src: \"{{ item.file }}.j2\"\n"
                    "    dest: \"/etc/k/{{ item.file }}\"\n  loop: \"{{ app_list }}\"\n"
                    "  register: out\n"
                    "- name: Apply\n  kube:\n    filename: \"/etc/k/{{ item.item.file }}\"\n"
                    "  loop: \"{{ out.results }}\"\n");
    write_temp_file(g_tmpdir, "roles/app/defaults/main.yml", "app_list:\n  - {file: a.yml}\n");
    write_temp_file(g_tmpdir, "roles/app/templates/a.yml.j2", "a: 1\n");
    write_temp_file(g_tmpdir, "roles/app/templates/b.yml.j2", "b: 1\n");
    write_temp_file(g_tmpdir, "roles/app/tasks/b.yml.j2", "b: 2\n");
    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/test_incr_deploys.db", g_tmpdir);
    static const char *const want[] = {
        "roles/app/templates/a.yml.j2", /* the full index */
        "roles/app/templates/a.yml.j2", /* a.yml.j2's body edited */
        "roles/app/templates/b.yml.j2", /* the defaults list names b.yml */
        "roles/app/tasks/b.yml.j2",     /* templates/b.yml.j2 deleted */
        "",                             /* the defaults deleted */
    };
    char path[1024];
    for (int step = 0; step < (int)(sizeof(want) / sizeof(want[0])); step++) {
        if (step == 1) {
            snprintf(path, sizeof(path), "%s/roles/app/templates/a.yml.j2", g_tmpdir);
            ASSERT_EQ(th_append_file(path, "a2: 2\n"), 0);
        } else if (step == 2) {
            write_temp_file(g_tmpdir, "roles/app/defaults/main.yml",
                            "app_list:\n  - {file: b.yml}\n");
        } else if (step == 3) {
            snprintf(path, sizeof(path), "%s/roles/app/templates/b.yml.j2", g_tmpdir);
            ASSERT_EQ(th_unlink_force(path), 0);
        } else if (step == 4) {
            snprintf(path, sizeof(path), "%s/roles/app/defaults/main.yml", g_tmpdir);
            ASSERT_EQ(th_unlink_force(path), 0);
        }
        cbm_pipeline_t *p = cbm_pipeline_new(g_tmpdir, db_path, CBM_MODE_FULL);
        ASSERT_NOT_NULL(p);
        ASSERT_EQ(cbm_pipeline_run(p), 0);
        cbm_store_t *s = cbm_store_open_path(db_path);
        ASSERT_NOT_NULL(s);
        char got[2048];
        bool ok = ansible_deploy_targets(s, cbm_pipeline_project_name(p), got, sizeof(got));
        cbm_store_close(s);
        cbm_pipeline_free(p);
        ASSERT_TRUE(ok);
        if (strcmp(got, want[step]) != 0) {
            fprintf(stderr, "step %d deploys got [%s] want [%s]\n", step, got, want[step]);
        }
        ASSERT_STR_EQ(got, want[step]);
    }
    teardown_test_repo();
    PASS();
}

/* Regression: a Terraform module's output read lives in one file
 * (infra/outputs.tf: module.net.vpc_id) and the module's source in another
 * (infra/main.tf). Pointing the source elsewhere edits main.tf alone; the
 * repair route recomputed the changed file's edges only, so the read -- held
 * by two UNCHANGED files, outputs.tf and modules/net/main.tf -- stayed in the
 * graph, which a full reindex no longer has. A Terraform input change now
 * declines to the full rebuild (closure_terraform_decline). */
TEST(pipeline_incremental_drops_terraform_reads_of_a_moved_module) {
    if (setup_test_repo() != 0) {
        FAIL("failed to create temp dir");
    }
    write_temp_file(g_tmpdir, "infra/main.tf",
                    "module \"net\" {\n  source = \"./modules/net\"\n}\n");
    write_temp_file(g_tmpdir, "infra/outputs.tf",
                    "output \"net_vpc\" {\n  value = module.net.vpc_id\n}\n");
    write_temp_file(g_tmpdir, "infra/modules/net/main.tf",
                    "output \"vpc_id\" {\n  value = \"x\"\n}\n");
    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/test_incr_tf.db", g_tmpdir);

    cbm_pipeline_t *p1 = cbm_pipeline_new(g_tmpdir, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p1);
    ASSERT_EQ(cbm_pipeline_run(p1), 0);
    cbm_store_t *s1 = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s1);
    ASSERT_TRUE(cross_file_edge_exists(s1, cbm_pipeline_project_name(p1), "output.net_vpc",
                                       "output.vpc_id", "USAGE"));
    cbm_store_close(s1);
    cbm_pipeline_free(p1);

    /* the module's source moves to a directory that does not exist */
    write_temp_file(g_tmpdir, "infra/main.tf",
                    "module \"net\" {\n  source = \"./modules/none\"\n}\n");

    cbm_pipeline_t *p2 = cbm_pipeline_new(g_tmpdir, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p2);
    ASSERT_EQ(cbm_pipeline_run(p2), 0);
    cbm_store_t *s2 = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(s2);
    ASSERT_FALSE(cross_file_edge_exists(s2, cbm_pipeline_project_name(p2), "output.net_vpc",
                                        "output.vpc_id", "USAGE"));
    cbm_store_close(s2);
    cbm_pipeline_free(p2);

    teardown_test_repo();
    PASS();
}

/* TS/JS receiver-aware weak-strategy suppression (#592/#606 direction; Perl
 * precedent #477). A member call x.foo() whose receiver TYPE the TS-LSP cannot
 * resolve (a regex literal `re.test()`) must NOT be bound to a same-named
 * project method by a weak short-name strategy — that fabricates a CALLS edge.
 * Type-resolved receivers (`c.test()` on a typed SalesforceRestClient) and bare
 * local calls must still resolve. < 50 files → sequential path (pass_calls.c).
 * RED before the fix: checkFormat->test exists via unique_name/suffix_match. */
static void write_temp_file(const char *dir, const char *name, const char *content);

typedef struct {
    const char *source_name;
    const char *target_name;
} PreciseReferencePair;

typedef struct {
    bool database_opened;
    bool query_ready;
    bool query_completed;
    int row_count;
    int valid_json_count;
    int exact_callee_count;
} NamedEdgePropertyObservation;

/* Read one named edge's persisted properties through SQLite's JSON functions.
 * The guarded json_extract is intentional: on the RED revision the parallel
 * usage emitter truncates the final `}` from a boundary-sized callee property.
 * json_valid must report that row without json_extract aborting the statement,
 * while the fixed revision must round-trip the complete callee value. */
static NamedEdgePropertyObservation observe_named_edge_callee_property(
    const char *db_path, const char *project, const char *edge_type, const char *source_name,
    const char *target_name, const char *expected_callee) {
    NamedEdgePropertyObservation observation = {0};
    sqlite3 *db = NULL;
    if (sqlite3_open_v2(db_path, &db, SQLITE_OPEN_READONLY, NULL) != SQLITE_OK) {
        if (db) {
            sqlite3_close(db);
        }
        return observation;
    }
    observation.database_opened = true;

    static const char sql[] = "SELECT e.properties, json_valid(e.properties), "
                              "CASE WHEN json_valid(e.properties) "
                              "THEN json_extract(e.properties, '$.callee') END "
                              "FROM edges e "
                              "JOIN nodes src ON src.id=e.source_id AND src.project=e.project "
                              "JOIN nodes tgt ON tgt.id=e.target_id AND tgt.project=e.project "
                              "WHERE e.project=?1 AND e.type=?2 AND src.name=?3 AND tgt.name=?4;";
    sqlite3_stmt *stmt = NULL;
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK ||
        sqlite3_bind_text(stmt, 1, project, -1, SQLITE_TRANSIENT) != SQLITE_OK ||
        sqlite3_bind_text(stmt, 2, edge_type, -1, SQLITE_TRANSIENT) != SQLITE_OK ||
        sqlite3_bind_text(stmt, 3, source_name, -1, SQLITE_TRANSIENT) != SQLITE_OK ||
        sqlite3_bind_text(stmt, 4, target_name, -1, SQLITE_TRANSIENT) != SQLITE_OK) {
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return observation;
    }
    observation.query_ready = true;

    int step_rc = SQLITE_OK;
    while ((step_rc = sqlite3_step(stmt)) == SQLITE_ROW) {
        observation.row_count++;
        if (sqlite3_column_int(stmt, 1) != 0) {
            observation.valid_json_count++;
        }
        const unsigned char *callee = sqlite3_column_text(stmt, 2);
        if (callee && strcmp((const char *)callee, expected_callee) == 0) {
            observation.exact_callee_count++;
        }
    }
    observation.query_completed = step_rc == SQLITE_DONE;
    sqlite3_finalize(stmt);
    sqlite3_close(db);
    return observation;
}

/* Count only edges of `edge_type` between the exact named source/target nodes.
 * The parity and incremental guards deliberately use unique symbol names, so
 * this canonicalizes across independent stores without depending on node IDs
 * or project-prefixed qualified names. */
static int named_edge_count(cbm_store_t *s, const char *project, const char *edge_type,
                            const char *source_name, const char *target_name) {
    cbm_edge_t *edges = NULL;
    int edge_count = 0;
    if (cbm_store_find_edges_by_type(s, project, edge_type, &edges, &edge_count) != CBM_STORE_OK) {
        return -1;
    }

    int matches = 0;
    for (int i = 0; i < edge_count; i++) {
        cbm_node_t source = {0};
        cbm_node_t target = {0};
        int source_ok = cbm_store_find_node_by_id(s, edges[i].source_id, &source) == CBM_STORE_OK;
        int target_ok = cbm_store_find_node_by_id(s, edges[i].target_id, &target) == CBM_STORE_OK;
        if (source_ok && target_ok && source.name && target.name &&
            strcmp(source.name, source_name) == 0 && strcmp(target.name, target_name) == 0) {
            matches++;
        }
        cbm_node_free_fields(&source);
        cbm_node_free_fields(&target);
    }
    if (edges) {
        cbm_store_free_edges(edges, edge_count);
    }
    return matches;
}

/* HTTP_CALLS edges out of the function `source_name` whose Route target's
 * qualified name contains `route_qn_part` (e.g. "__route__GET__"). */
static int http_calls_to_route(cbm_store_t *s, const char *project, const char *source_name,
                               const char *route_qn_part) {
    cbm_edge_t *edges = NULL;
    int edge_count = 0;
    if (cbm_store_find_edges_by_type(s, project, "HTTP_CALLS", &edges, &edge_count) !=
        CBM_STORE_OK) {
        return -1;
    }
    int matches = 0;
    for (int i = 0; i < edge_count; i++) {
        cbm_node_t source = {0};
        cbm_node_t target = {0};
        int source_ok = cbm_store_find_node_by_id(s, edges[i].source_id, &source) == CBM_STORE_OK;
        int target_ok = cbm_store_find_node_by_id(s, edges[i].target_id, &target) == CBM_STORE_OK;
        if (source_ok && target_ok && source.name && target.qualified_name &&
            strcmp(source.name, source_name) == 0 && strstr(target.qualified_name, route_qn_part)) {
            matches++;
        }
        cbm_node_free_fields(&source);
        cbm_node_free_fields(&target);
    }
    if (edges) {
        cbm_store_free_edges(edges, edge_count);
    }
    return matches;
}

/* Like named_edge_count, but distinguish same-named targets by their source
 * file. Semantic-control fixtures intentionally keep the exported short name
 * identical in two modules so a project-wide unique-name fallback cannot make
 * an alias-mapping assertion pass accidentally. */
static int named_edge_to_file_count(cbm_store_t *s, const char *project, const char *edge_type,
                                    const char *source_name, const char *target_name,
                                    const char *target_file_path) {
    cbm_edge_t *edges = NULL;
    int edge_count = 0;
    if (cbm_store_find_edges_by_type(s, project, edge_type, &edges, &edge_count) != CBM_STORE_OK) {
        return -1;
    }

    int matches = 0;
    for (int i = 0; i < edge_count; i++) {
        cbm_node_t source = {0};
        cbm_node_t target = {0};
        int source_ok = cbm_store_find_node_by_id(s, edges[i].source_id, &source) == CBM_STORE_OK;
        int target_ok = cbm_store_find_node_by_id(s, edges[i].target_id, &target) == CBM_STORE_OK;
        if (source_ok && target_ok && source.name && target.name && target.file_path &&
            strcmp(source.name, source_name) == 0 && strcmp(target.name, target_name) == 0 &&
            strcmp(target.file_path, target_file_path) == 0) {
            matches++;
        }
        cbm_node_free_fields(&source);
        cbm_node_free_fields(&target);
    }
    if (edges) {
        cbm_store_free_edges(edges, edge_count);
    }
    return matches;
}

/* Count exact-name nodes without depending on project-prefixed qualified names.
 * Export-XML relationship tests use this as an anti-vacuous guard: the
 * transcoded methods must exist even when their extracted relationships were
 * accidentally discarded. */
static int named_node_count(cbm_store_t *s, const char *project, const char *name) {
    cbm_node_t *nodes = NULL;
    int count = 0;
    if (cbm_store_find_nodes_by_name(s, project, name, &nodes, &count) != CBM_STORE_OK) {
        return -1;
    }
    if (nodes) {
        cbm_store_free_nodes(nodes, count);
    }
    return count;
}

static int fixture_node_count(cbm_store_t *store, const char *project, const char *path,
                              const char *name, const char *label) {
    cbm_node_t *nodes = NULL;
    int count = 0;
    if (cbm_store_find_nodes_by_name(store, project, name, &nodes, &count) != CBM_STORE_OK) {
        return -1;
    }
    int found = 0;
    for (int i = 0; i < count; i++) {
        if (nodes[i].file_path && nodes[i].label && strcmp(nodes[i].file_path, path) == 0 &&
            strcmp(nodes[i].label, label) == 0) {
            found++;
        }
    }
    if (nodes) {
        cbm_store_free_nodes(nodes, count);
    }
    return found;
}

/* Edges of `edge_type` from the node named `source_name` to the node named
 * `target_name` that carries `target_label`. */
static int labeled_edge_count(cbm_store_t *s, const char *project, const char *edge_type,
                              const char *source_name, const char *target_name,
                              const char *target_label) {
    cbm_edge_t *edges = NULL;
    int edge_count = 0;
    if (cbm_store_find_edges_by_type(s, project, edge_type, &edges, &edge_count) != CBM_STORE_OK) {
        return -1;
    }
    int matches = 0;
    for (int i = 0; i < edge_count; i++) {
        cbm_node_t source = {0};
        cbm_node_t target = {0};
        int source_ok = cbm_store_find_node_by_id(s, edges[i].source_id, &source) == CBM_STORE_OK;
        int target_ok = cbm_store_find_node_by_id(s, edges[i].target_id, &target) == CBM_STORE_OK;
        if (source_ok && target_ok && source.name && target.name && target.label &&
            strcmp(source.name, source_name) == 0 && strcmp(target.name, target_name) == 0 &&
            strcmp(target.label, target_label) == 0) {
            matches++;
        }
        cbm_node_free_fields(&source);
        cbm_node_free_fields(&target);
    }
    if (edges) {
        cbm_store_free_edges(edges, edge_count);
    }
    return matches;
}

/* A Java field and a same-named method of one class keep their own nodes (the
 * field is fenced `<Owner>.<name>#field`), and a write or a read of the field
 * reaches the field, never the method; the method keeps its calls. The setter
 * writing its own namesake was a self-edge before, so it was dropped. */
TEST(pipeline_field_named_like_method_keeps_its_reads_and_writes) {
    char tmp[256];
    snprintf(tmp, sizeof(tmp), "/tmp/cbm_fieldfence_XXXXXX");
    ASSERT_NOT_NULL(cbm_mkdtemp(tmp));
    th_write_file(TH_PATH(tmp, "src/demo/Starter.java"),
                  "package demo;\n\npublic class Starter {\n"
                  "    private String executable;\n\n"
                  "    public Starter executable(String path) {\n"
                  "        this.executable = path;\n"
                  "        return this;\n    }\n\n"
                  "    public String show() {\n        return executable;\n    }\n\n"
                  "    public static void run() {\n"
                  "        new Starter().executable(\"x\").show();\n    }\n}\n");
    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/fence.db", tmp);
    cbm_pipeline_t *p = cbm_pipeline_new(tmp, db_path, CBM_MODE_FULL);
    ASSERT_NOT_NULL(p);
    ASSERT_EQ(cbm_pipeline_run(p), 0);
    const char *project = cbm_pipeline_project_name(p);
    cbm_store_t *store = cbm_store_open_path(db_path);
    ASSERT_NOT_NULL(store);
    ASSERT_EQ(named_node_count(store, project, "executable"), 2);
    ASSERT_EQ(labeled_edge_count(store, project, "WRITES", "executable", "executable", "Field"), 1);
    ASSERT_EQ(labeled_edge_count(store, project, "WRITES", "executable", "executable", "Method"),
              0);
    ASSERT_EQ(labeled_edge_count(store, project, "USAGE", "show", "executable", "Field"), 1);
    ASSERT_EQ(labeled_edge_count(store, project, "USAGE", "show", "executable", "Method"), 0);
    ASSERT_EQ(labeled_edge_count(store, project, "CALLS", "run", "executable", "Method"), 1);
    cbm_store_close(store);
    cbm_pipeline_free(p);
    th_cleanup(tmp);
    PASS();
}

typedef struct {
    int run_rc;
    bool store_opened;
    int run_nodes;
    int execute_nodes;
    int run_execute_calls;
    int shared_payload_nodes;
    int run_shared_payload_usages;
} ObjectScriptExportObservation;

static ObjectScriptExportObservation observe_objectscript_export(const char *repo_path,
                                                                 const char *db_name) {
    ObjectScriptExportObservation observation = {
        .run_rc = -1,
        .store_opened = false,
        .run_nodes = -1,
        .execute_nodes = -1,
        .run_execute_calls = -1,
        .shared_payload_nodes = -1,
        .run_shared_payload_usages = -1,
    };
    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/%s", repo_path, db_name);
    cbm_pipeline_t *pipeline = cbm_pipeline_new(repo_path, db_path, CBM_MODE_FULL);
    if (!pipeline) {
        return observation;
    }

    observation.run_rc = cbm_pipeline_run(pipeline);
    const char *project = cbm_pipeline_project_name(pipeline);
    cbm_store_t *store = cbm_store_open_path(db_path);
    observation.store_opened = store != NULL;
    if (store && project) {
        observation.run_nodes = named_node_count(store, project, "Run");
        observation.execute_nodes = named_node_count(store, project, "Execute");
        observation.run_execute_calls = named_edge_count(store, project, "CALLS", "Run", "Execute");
        observation.shared_payload_nodes = named_node_count(store, project, "SharedPayload");
        observation.run_shared_payload_usages =
            named_edge_count(store, project, "USAGE", "Run", "SharedPayload");
    }
    if (store) {
        cbm_store_close(store);
    }
    cbm_pipeline_free(pipeline);
    return observation;
}

/* Studio Export XML is transformed into ObjectScript UDL during extraction.
 * The transformed definitions already survive, but the old sequential and
 * fused-parallel special cases freed each transformed result after inserting
 * only its definitions. Calls/usages therefore vanished even though direct
 * extraction of the same generated UDL found them.
 *
 * One shared multi-class fixture is indexed through both execution paths. The
 * 50 filler files only select the fused path; CBM_INDEX_SINGLE_THREAD forces
 * the first run through the sequential path without duplicating setup.
 * RED before the fix: Run and Execute each exist once, Run -> Execute is 0 in
 * both stores. GREEN requires exactly one CALLS edge in each store. */
TEST(pipeline_objectscript_export_preserves_calls_sequential_parallel) {
    static const char export_xml[] = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                                     "<Export generator=\"Cache\" version=\"25\">\n"
                                     "<Class name=\"Test.Worker\">\n"
                                     "<Method name=\"Execute\">\n"
                                     "<ClassMethod>1</ClassMethod>\n"
                                     "<FormalSpec>pValue:%String</FormalSpec>\n"
                                     "<ReturnType>%Status</ReturnType>\n"
                                     "<Implementation><![CDATA[\n"
                                     "    Quit $$$OK\n"
                                     "]]></Implementation>\n"
                                     "</Method>\n"
                                     "</Class>\n"
                                     "<Class name=\"Test.Caller\">\n"
                                     "<Method name=\"Run\">\n"
                                     "<ClassMethod>1</ClassMethod>\n"
                                     "<FormalSpec>pPayload:%String</FormalSpec>\n"
                                     "<ReturnType>%Status</ReturnType>\n"
                                     "<Implementation><![CDATA[\n"
                                     "    Do ##class(Test.Worker).Execute(pPayload)\n"
                                     "    Quit $$$OK\n"
                                     "]]></Implementation>\n"
                                     "</Method>\n"
                                     "</Class>\n"
                                     "</Export>\n";

    char tmp[256];
    snprintf(tmp, sizeof(tmp), "/tmp/cbm_export_rel_XXXXXX");
    if (!cbm_mkdtemp(tmp)) {
        FAIL("tmpdir");
    }
    char export_path[512];
    snprintf(export_path, sizeof(export_path), "%s/studio-export.xml", tmp);
    if (th_write_file(export_path, export_xml) != 0) {
        th_rmtree(tmp);
        FAIL("failed to write Studio Export fixture");
    }

    /* Export XML plus 50 trackable fillers exceeds MIN_FILES_FOR_PARALLEL. */
    for (int i = 0; i < 50; i++) {
        char filename[64];
        char path[512];
        char source[128];
        snprintf(filename, sizeof(filename), "export_pad_%02d.ts", i);
        snprintf(path, sizeof(path), "%s/%s", tmp, filename);
        snprintf(source, sizeof(source), "export function exportPad%02d(): number { return %d; }\n",
                 i, i);
        if (th_write_file(path, source) != 0) {
            th_rmtree(tmp);
            FAIL("failed to write parallel-selection fixture");
        }
    }

    char *old_workers = getenv("CBM_WORKERS");
    char *saved_workers = old_workers ? strdup(old_workers) : NULL;
    char *old_single = getenv("CBM_INDEX_SINGLE_THREAD");
    char *saved_single = old_single ? strdup(old_single) : NULL;

    cbm_setenv("CBM_INDEX_SINGLE_THREAD", "1", 1);
    ObjectScriptExportObservation sequential =
        observe_objectscript_export(tmp, "export-sequential.db");

    cbm_unsetenv("CBM_INDEX_SINGLE_THREAD");
    cbm_setenv("CBM_WORKERS", "4", 1);
    ObjectScriptExportObservation parallel = observe_objectscript_export(tmp, "export-parallel.db");

    if (saved_workers) {
        cbm_setenv("CBM_WORKERS", saved_workers, 1);
        free(saved_workers);
    } else {
        cbm_unsetenv("CBM_WORKERS");
    }
    if (saved_single) {
        cbm_setenv("CBM_INDEX_SINGLE_THREAD", saved_single, 1);
        free(saved_single);
    } else {
        cbm_unsetenv("CBM_INDEX_SINGLE_THREAD");
    }
    th_rmtree(tmp);

    ASSERT_EQ(sequential.run_rc, 0);
    ASSERT_TRUE(sequential.store_opened);
    ASSERT_EQ(sequential.run_nodes, 1);
    ASSERT_EQ(sequential.execute_nodes, 1);

    ASSERT_EQ(parallel.run_rc, 0);
    ASSERT_TRUE(parallel.store_opened);
    ASSERT_EQ(parallel.run_nodes, 1);
    ASSERT_EQ(parallel.execute_nodes, 1);
    if (sequential.run_execute_calls != 1 || parallel.run_execute_calls != 1) {
        fprintf(stderr,
                "  [objectscript-export] invariant=transformed_calls_preserved "
                "expected=1/1 actual=%d/%d\n",
                sequential.run_execute_calls, parallel.run_execute_calls);
    }
    ASSERT_TRUE(sequential.run_execute_calls == 1 && parallel.run_execute_calls == 1);
    PASS();
}

static int format_objectscript_export_lifecycle_fixture(char *xml, size_t xml_capacity,
                                                        const char *default_value) {
    int written = snprintf(xml, xml_capacity,
                           "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                           "<Export generator=\"Cache\" version=\"25\">\n"
                           "<Class name=\"Test.Worker\">\n"
                           "<Method name=\"Execute\">\n"
                           "<ClassMethod>1</ClassMethod>\n"
                           "<FormalSpec>pValue:%%String</FormalSpec>\n"
                           "<ReturnType>%%Status</ReturnType>\n"
                           "<Implementation><![CDATA[\n"
                           "    Quit $$$OK\n"
                           "]]></Implementation>\n"
                           "</Method>\n"
                           "</Class>\n"
                           "<Class name=\"Test.Caller\">\n"
                           "<Parameter name=\"SharedPayload\"><Default>%s</Default></Parameter>\n"
                           "<Method name=\"Run\">\n"
                           "<ClassMethod>1</ClassMethod>\n"
                           "<FormalSpec>watched:%%String</FormalSpec>\n"
                           "<ReturnType>%%Status</ReturnType>\n"
                           "<Implementation><![CDATA[\n"
                           "    Do ##class(Test.Worker).Execute(watched)\n"
                           "    Quit $$$OK\n"
                           "]]></Implementation>\n"
                           "</Method>\n"
                           "</Class>\n"
                           "</Export>\n",
                           default_value);
    if (written <= 0 || (size_t)written >= xml_capacity) {
        return -1;
    }
    return written;
}

static int write_objectscript_export_lifecycle_fixture(const char *path,
                                                       const char *default_value) {
    char xml[4096];
    int written = format_objectscript_export_lifecycle_fixture(xml, sizeof(xml), default_value);
    if (written < 0) {
        return -1;
    }
    return th_write_file(path, xml);
}

/* A changed Studio Export file must keep its transformed carriers alive for
 * every incremental resolution pass. Compare the incrementally rebuilt graph
 * with a clean full sequential build of the same replacement XML. Direct
 * extraction separately proves that the transformed aggregate retains the
 * method-argument USAGE carrier; formal parameters are not graph targets, so
 * graph resolution of that carrier is outside this lifecycle regression.
 * ObjectScript has no per-file or cross-file LSP dispatcher, so it cannot
 * produce a resolved_calls semantic carrier to assert here.
 *
 * RED before the incremental cache lifecycle fix: definitions survived, but
 * the changed Export was re-read as raw XML by later passes, so Run->Execute
 * CALLS was absent from the incremental graph. */
TEST(pipeline_objectscript_export_incremental_matches_full_relationships) {
    char tmp[256];
    snprintf(tmp, sizeof(tmp), "/tmp/cbm_export_incr_XXXXXX");
    if (!cbm_mkdtemp(tmp)) {
        FAIL("tmpdir");
    }
    char export_path[512];
    snprintf(export_path, sizeof(export_path), "%s/studio-export.xml", tmp);
    if (write_objectscript_export_lifecycle_fixture(export_path, "initial") != 0) {
        th_rmtree(tmp);
        FAIL("failed to write initial Studio Export fixture");
    }

    char carrier_xml[4096];
    int carrier_xml_len =
        format_objectscript_export_lifecycle_fixture(carrier_xml, sizeof(carrier_xml), "initial");
    if (carrier_xml_len < 0) {
        th_rmtree(tmp);
        FAIL("failed to format Studio Export carrier fixture");
    }
    cbm_init();
    CBMFileResult *carrier_result = cbm_pipeline_extract_objectscript_export(
        carrier_xml, carrier_xml_len, "export-lifecycle", "studio-export.xml", NULL, NULL);
    if (!carrier_result) {
        th_rmtree(tmp);
        FAIL("failed to extract Studio Export carrier fixture");
    }
    bool found_argument_usage = false;
    for (int i = 0; i < carrier_result->usages.count; i++) {
        const CBMUsage *usage = &carrier_result->usages.items[i];
        if (usage->ref_name && strcmp(usage->ref_name, "watched") == 0 &&
            usage->enclosing_func_qn && strstr(usage->enclosing_func_qn, ".Run")) {
            found_argument_usage = true;
            break;
        }
    }
    cbm_free_result(carrier_result);
    if (!found_argument_usage) {
        th_rmtree(tmp);
        FAIL("Studio Export aggregate lost method-argument USAGE carrier");
    }

    char *old_single = getenv("CBM_INDEX_SINGLE_THREAD");
    char *saved_single = old_single ? strdup(old_single) : NULL;
    cbm_setenv("CBM_INDEX_SINGLE_THREAD", "1", 1);

    ObjectScriptExportObservation initial =
        observe_objectscript_export(tmp, "export-incremental.db");

    if (write_objectscript_export_lifecycle_fixture(export_path,
                                                    "replacement-with-a-different-size") != 0) {
        if (saved_single) {
            cbm_setenv("CBM_INDEX_SINGLE_THREAD", saved_single, 1);
            free(saved_single);
        } else {
            cbm_unsetenv("CBM_INDEX_SINGLE_THREAD");
        }
        th_rmtree(tmp);
        FAIL("failed to write replacement Studio Export fixture");
    }

    /* Same DB routes through incremental; a fresh DB is the full reference. */
    ObjectScriptExportObservation incremental =
        observe_objectscript_export(tmp, "export-incremental.db");
    ObjectScriptExportObservation full =
        observe_objectscript_export(tmp, "export-full-reference.db");

    if (saved_single) {
        cbm_setenv("CBM_INDEX_SINGLE_THREAD", saved_single, 1);
        free(saved_single);
    } else {
        cbm_unsetenv("CBM_INDEX_SINGLE_THREAD");
    }
    th_rmtree(tmp);

    ASSERT_EQ(initial.run_rc, 0);
    ASSERT_TRUE(initial.store_opened);
    ASSERT_EQ(initial.run_execute_calls, 1);

    ASSERT_EQ(incremental.run_rc, 0);
    ASSERT_TRUE(incremental.store_opened);
    ASSERT_EQ(full.run_rc, 0);
    ASSERT_TRUE(full.store_opened);
    ASSERT_EQ(incremental.run_nodes, full.run_nodes);
    ASSERT_EQ(incremental.execute_nodes, full.execute_nodes);
    ASSERT_EQ(incremental.shared_payload_nodes, full.shared_payload_nodes);
    ASSERT_EQ(incremental.run_execute_calls, full.run_execute_calls);
    ASSERT_EQ(incremental.run_shared_payload_usages, full.run_shared_payload_usages);
    ASSERT_EQ(full.run_nodes, 1);
    ASSERT_EQ(full.execute_nodes, 1);
    ASSERT_EQ(full.shared_payload_nodes, 1);
    ASSERT_EQ(full.run_execute_calls, 1);
    PASS();
}

/* Cross-language unique_name leak. Every Python file injects a few builtin
 * stub definitions (builtins.dict.get, builtins.len, ...; see
 * internal/cbm/lsp/py_builtins.c) into the project registry. A JS Express
 * registration `app.get('/users', listUsers)` has no LSP target, falls
 * through to the registry, and its short name "get" had exactly one
 * candidate project-wide: Python's builtins.dict.get (strategy unique_name).
 * The non-empty resolution skipped the route-registration fallback (it runs
 * only on an EMPTY resolution), and the weak-member guard then dropped the
 * plain CALLS edge, so the Route node and its HANDLES edge vanished -- on the
 * sequential and the parallel path alike, and on an incremental reindex whose
 * registry is re-seeded from stored nodes (the builtin stubs survive there
 * even after the last .py file is gone).
 *
 * The same leak fabricates CALLS edges on both paths: a bare JS `print(msg)`
 * bound to Python's builtins.print by unique_name. `cache.get(key)` guards the
 * other side of the veto: an unresolved route verb without a route path must
 * not become a CALLS self-loop on the parallel path.
 *
 * The Python control proves the builtins stay reachable from Python itself:
 * lookup() -> builtins.dict.get (lsp_generic_method) and -> builtins.len. */
typedef struct {
    int run_rc;
    bool store_opened;
    int routes;      /* Route node "/users" */
    int handles;     /* listUsers -[HANDLES]-> "/users" */
    int py_dict_get; /* lookup -[CALLS]-> get */
    int py_len;      /* lookup -[CALLS]-> len */
    int js_print;    /* report -[CALLS]-> print (JS global, never Python's) */
    int self_loop;   /* readCache -[CALLS]-> readCache (unresolved route verb) */
} XlangRouteObservation;

static XlangRouteObservation observe_xlang_route(const char *repo_path, const char *db_name) {
    XlangRouteObservation o = {.run_rc = -1,
                               .routes = -1,
                               .handles = -1,
                               .py_dict_get = -1,
                               .py_len = -1,
                               .js_print = -1,
                               .self_loop = -1};
    char db_path[512];
    snprintf(db_path, sizeof(db_path), "%s/%s", repo_path, db_name);
    cbm_pipeline_t *pipeline = cbm_pipeline_new(repo_path, db_path, CBM_MODE_FULL);
    if (!pipeline) {
        return o;
    }
    o.run_rc = cbm_pipeline_run(pipeline);
    const char *project = cbm_pipeline_project_name(pipeline);
    cbm_store_t *store = cbm_store_open_path(db_path);
    o.store_opened = store != NULL;
    if (store && project) {
        o.routes = named_node_count(store, project, "/users");
        o.handles = named_edge_count(store, project, "HANDLES", "listUsers", "/users");
        o.py_dict_get = named_edge_count(store, project, "CALLS", "lookup", "get");
        o.py_len = named_edge_count(store, project, "CALLS", "lookup", "len");
        o.js_print = named_edge_count(store, project, "CALLS", "report", "print");
        o.self_loop = named_edge_count(store, project, "CALLS", "readCache", "readCache");
    }
    if (store) {
        cbm_store_close(store);
    }
    cbm_pipeline_free(pipeline);
    return o;
}

static const char XLANG_APP_JS[] = "const express = require('express');\n"
                                   "const app = express();\n"
                                   "\n"
                                   "function listUsers(req, res) {\n"
                                   "  res.json([]);\n"
                                   "}\n"
                                   "\n"
                                   "app.get('/users', listUsers);\n"
                                   "\n"
                                   "function report(msg) {\n"
                                   "  print(msg);\n"
                                   "}\n"
                                   "\n"
                                   "function readCache(cache, key) {\n"
                                   "  return cache.get(key);\n"
                                   "}\n"
                                   "module.exports = { app, report, readCache };\n";

static const char XLANG_TOOL_PY[] = "def lookup(xs):\n"
                                    "    d = {\"k\": 1}\n"
                                    "    n = len(xs)\n"
                                    "    return d.get(\"k\"), n\n";

/* Writes app.js + tool.py + `pad` JS filler files (the fillers only select the
 * parallel path: more than MIN_FILES_FOR_PARALLEL files). 0 on success. */
static int write_xlang_route_fixture(const char *dir, int pad) {
    char path[512];
    snprintf(path, sizeof(path), "%s/app.js", dir);
    if (th_write_file(path, XLANG_APP_JS) != 0) {
        return -1;
    }
    snprintf(path, sizeof(path), "%s/tool.py", dir);
    if (th_write_file(path, XLANG_TOOL_PY) != 0) {
        return -1;
    }
    for (int i = 0; i < pad; i++) {
        char source[128];
        snprintf(path, sizeof(path), "%s/xlang_pad_%02d.js", dir, i);
        snprintf(source, sizeof(source), "function xlangPad%02d() { return %d; }\n", i, i);
        if (th_write_file(path, source) != 0) {
            return -1;
        }
    }
    return 0;
}

/* Saves and overrides the two worker-selection variables. */
typedef struct {
    char *workers;
    char *single;
} XlangEnvSave;

static XlangEnvSave xlang_env_select(bool parallel) {
    XlangEnvSave save = {0};
    const char *w = getenv("CBM_WORKERS");
    const char *s = getenv("CBM_INDEX_SINGLE_THREAD");
    save.workers = w ? strdup(w) : NULL;
    save.single = s ? strdup(s) : NULL;
    if (parallel) {
        cbm_unsetenv("CBM_INDEX_SINGLE_THREAD");
        cbm_setenv("CBM_WORKERS", "4", 1);
    } else {
        cbm_setenv("CBM_INDEX_SINGLE_THREAD", "1", 1);
    }
    return save;
}

static void xlang_env_restore(XlangEnvSave *save) {
    if (save->workers) {
        cbm_setenv("CBM_WORKERS", save->workers, 1);
        free(save->workers);
    } else {
        cbm_unsetenv("CBM_WORKERS");
    }
    if (save->single) {
        cbm_setenv("CBM_INDEX_SINGLE_THREAD", save->single, 1);
        free(save->single);
    } else {
        cbm_unsetenv("CBM_INDEX_SINGLE_THREAD");
    }
    save->workers = NULL;
    save->single = NULL;
}

static XlangRouteObservation run_xlang_route_case(bool parallel, int pad) {
    XlangRouteObservation o = {.run_rc = -1};
    char tmp[256];
    snprintf(tmp, sizeof(tmp), "/tmp/cbm_xlang_route_XXXXXX");
    if (!cbm_mkdtemp(tmp)) {
        return o;
    }
    if (write_xlang_route_fixture(tmp, pad) == 0) {
        XlangEnvSave save = xlang_env_select(parallel);
        o = observe_xlang_route(tmp, "xlang.db");
        xlang_env_restore(&save);
    }
    th_rmtree(tmp);
    return o;
}

