    ASSERT_TRUE(cross_file_edge_exists(s, project, "Reset", "err", "WRITES"));
    ASSERT_TRUE(cross_file_edge_exists(s, project, "Reset", "n", "USAGE"));

    cbm_store_close(s);
    cbm_pipeline_free(p);
