    ASSERT_NOT_NULL(p);
    ASSERT_EQ(cbm_pipeline_run(p), 0);
    cbm_pipeline_free(p);
    cbm_store_t *s = cbm_store_open_path(db);
    ASSERT_NOT_NULL(s);
    int before = doc_candidate_row_count(s);
